358	        {
359	            Array.Copy(Genes, idx + 1, Genes, idx, Genes.Length - 1 - idx);
360	            var lastMove = TMove.Decode((int)Genes[Genes.Length - 1]);
361	            lastMove.Axis = (lastMove.Axis + 1) % TAffine.N;
362	            var planeAxes = lastMove.GetPlaneAxes();
363	            while (planeAxes[0] == lastMove.Axis || planeAxes[1] == lastMove.Axis)
364	            {
365	                lastMove.Plane = (lastMove.Plane + 1) % TAffine.Planes.Length;
366	                planeAxes = TAffine.Planes[lastMove.Plane];
367	            }
368	            Genes[Genes.Length - 1] = lastMove.Encode();
369	            BestMovesCount--;
370	        }
