211	        public static unsafe class HyperCubeSimdKernel
212	        {
213	            /// <summary>
214	            /// Obraca wybraną parę wierszy macierzy orientacji (płaszczyznę obrotu) dla wszystkich kubików w hiperpłaszczyźnie.
215	            /// Wykonuje operację dla 32 elementów jednocześnie przy użyciu AVX2.
216	            /// </summary>
217	            /// <param name="rowI">Wskaźnik do ciągłej tablicy elementów wiersza I (wartości sbyte)</param>
218	            /// <param name="rowJ">Wskaźnik do ciągłej tablicy elementów wiersza J (wartości sbyte)</param>
219	            /// <param name="count">Liczba kubików w modyfikowanej hiperpłaszczyźnie</param>
220	            /// <param name="rotationModifier">Krotność obrotu: 1 = 90°, 2 = 180°, 3 = 270°</param>
221	            [MethodImpl(MethodImplOptions.AggressiveInlining)]
222	            public static void RotateHiperpaneOrientations(sbyte* rowI, sbyte* rowJ, int count, int rotationModifier)
223	            {
224	                // Sprawdzenie sprzętowe - jeśli procesor nie wspiera AVX2, przechodzimy do kodu zapasowego (Fallback)
225	                if (!Avx2.IsSupported)
226	                {
227	                    RotateFallback(rowI, rowJ, count, rotationModifier);
228	                    return;
229	                }
230	
231	                int simdBlockSize = Vector256<sbyte>.Count; // = 32
232	                int vectorCount = simdBlockSize * (count / simdBlockSize);
233	
234	                Vector256<sbyte> vZero = Vector256<sbyte>.Zero;
235	
236	                // Główna pętla SIMD - przetwarzanie paczek po 32 kubiki naraz
237	                for (int b = 0; b < vectorCount; b += simdBlockSize)
238	                {
239	                    // 1. Ładowanie 32 elementów z pamięci RAM bezpośrednio do rejestrów procesora
240	                    Vector256<sbyte> vM_ik = Avx2.LoadVector256(rowI + b);
241	                    Vector256<sbyte> vM_jk = Avx2.LoadVector256(rowJ + b);
242	
243	                    switch (rotationModifier)
244	                    {
245	                        case 0: // Obrót o 90°: New_I = -J, New_J = I
246	                            {
247	                                Vector256<sbyte> vNewM_ik = Avx2.Subtract(vZero, vM_jk); // -M_jk
248	                                Avx2.Store(rowI + b, vNewM_ik);
249	                                Avx2.Store(rowJ + b, vM_ik);
250	                            }
251	                            break;
252	
253	                        case 1: // Obrót o 180°: New_I = -I, New_J = -J
254	                            {
255	                                Vector256<sbyte> vNewM_ik = Avx2.Subtract(vZero, vM_ik); // -M_ik
256	                                Vector256<sbyte> vNewM_jk = Avx2.Subtract(vZero, vM_jk); // -M_jk
257	                                Avx2.Store(rowI + b, vNewM_ik);
258	                                Avx2.Store(rowJ + b, vNewM_jk);
259	                            }
260	                            break;
261	
262	                        case 2: // Obrót o 270°: New_I = J, New_J = -I
263	                            {
264	                                Vector256<sbyte> vNewM_jk = Avx2.Subtract(vZero, vM_ik); // -M_ik
265	                                Avx2.Store(rowI + b, vM_jk);
266	                                Avx2.Store(rowJ + b, vNewM_jk);
267	                            }
268	                            break;
269	                    }
270	                }
271	
272	                // Pętla sprzątająca (Tail Cleanup) - obsługuje resztę elementów, jeśli rozmiar warstwy nie dzieli się przez 32
273	                RotateFallback(rowI + vectorCount, rowJ + vectorCount, count - vectorCount, rotationModifier);
274	            }
