290	            /// <summary>
291	            /// Klasyczny, sekwencyjny kod zapasowy (Fallback) używany dla końcówki tablicy lub na starych procesorach.
292	            /// </summary>
293	            private static void RotateFallback(sbyte* rowI, sbyte* rowJ, int count, int rotationModifier)
294	            {
295	                for (int b = 0; b < count; b++)
296	                {
297	                    sbyte iVal = rowI[b];
298	                    sbyte jVal = rowJ[b];
299	
300	                    switch (rotationModifier)
301	                    {
302	                        case 1: // 90°
303	                            rowI[b] = (sbyte)(-jVal);
304	                            rowJ[b] = iVal;
305	                            break;
306	                        case 2: // 180°
307	                            rowI[b] = (sbyte)(-iVal);
308	                            rowJ[b] = (sbyte)(-jVal);
309	                            break;
310	                        case 3: // 270°
311	                            rowI[b] = jVal;
312	                            rowJ[b] = (sbyte)(-iVal);
313	                            break;
314	                    }
315	                }
316	            }
317	        }
