341	        public unsafe void Turn(TMove move)
342	        {
343	            var plane = TAffine.Planes[move.Plane];
344	            var rot = TCubie.SetAngle(move.Angle + 1);
345	            var K = Cubies.Length / Size;
346	            var active_indices = new int[K];
347	            int k = 0;
348	            var h = move.Slice - C;
349	            // P[j][id] - statyczna tablica z oryginalnymi pozycjami wszystkich kubików
350	            // Szukamy kubików, których aktualna pozycja w osi 'a' równa się wysokości warstwy 'h'
351	            for (int id = 0; id < Cubies.Length; ++id)
352	                for (int j = 0; j < TAffine.N; ++j)
353	                    if (M[move.Axis][j][id] != 0)
354	                    {
355	                        var actual_pos_a = M[move.Axis][j][id] * P[j][id];
356	                        if (actual_pos_a == h)
357	                            active_indices[k++] = id;
358	                        break; // W wierszu macierzy permutacyjnej jest tylko jedna niezerowa wartość
359	                    }
360	            sbyte cosA = (sbyte)rot.X;
361	            sbyte sinA = (sbyte)rot.Y;
362	            unchecked
363	            {
364	                sbyte[][] rowA = M[plane[0]];
365	                sbyte[][] rowB = M[plane[1]];
366	
367	                for (int col = 0; col < TAffine.N; ++col)
368	                {
369	                    sbyte[] colA = rowA[col];
370	                    sbyte[] colB = rowB[col];
371	
372	                    for (k = 0; k < K; ++k)
373	                    {
374	                        int id = active_indices[k];
375	
376	                        sbyte origA = colA[id];
377	                        sbyte origB = colB[id];
378	
379	                        // Jedna uniwersalna formuła dla KAŻDEGO kąta!
380	                        // Zmiana znaku i zamiana wierszy dzieje się automatycznie przez mnożenie przez 0, 1 lub -1
381	                        colA[id] = (sbyte)(origA * cosA - origB * sinA);
382	                        colB[id] = (sbyte)(origA * sinA + origB * cosA);
383	                    }
384	                }
385	            }
386	        }
