865	        static List<int[]> DoPermute(int[] nums, int start, int end)
866	        {
867	            var result = new List<int[]>();
868	            if (start == end)
869	            {
870	                var perm = new int[nums.Length];
871	                Array.Copy(nums, perm, nums.Length);
872	                result.Add(perm);
873	            }
874	            else
875	                for (var i = start; i <= end; i++)
876	                {
877	                    Swap(ref nums[start], ref nums[i]);
878	                    result.AddRange(DoPermute(nums, start + 1, end));
879	                    Swap(ref nums[start], ref nums[i]);
880	                }
881	            return result;
882	        }
