924	        public List<int> GetOrder()
925	        {
926	            var mask = new bool[TAffine.N, TAffine.N];
927	            var planes = new List<int>();
928	            for (int i = 0; i < TAffine.Planes.Length; i++)
929	                planes.Add(i);
930	            var caseCount = 1;
931	            var order = new List<int>();
932	            while (planes.Count > 0)
933	            {
934	                var pool = new List<int>();
935	                for (int i = 0; i < planes.Count; i++)
936	                {
937	                    var planeIdx = TAffine.Planes[planes[i]];
938	                    var n = planeIdx[0];
939	                    var m = planeIdx[1];
940	                    if (n == 0 || mask[m, n - 1] && mask[n, n - 1])
941	                        pool.Add(planes[i]);
942	                }
943	                caseCount *= pool.Count;
944	                var plane = pool[TChromosome.Rnd.Next(pool.Count)];
945	                planes.Remove(plane);
946	                var maskIdx = TAffine.Planes[plane];
947	                mask[maskIdx[1], maskIdx[0]] = true;
948	                order.Add(plane);
949	            }
950	            return order;
951	        }
