953	        bool NonStandard(int[] order)
954	        {
955	            if (order == null) return false;
956	            var mask = new bool[TAffine.N, TAffine.N];
957	            for (int i = 0; i < order.Length; i++)
958	            {
959	                var planeIdx = TAffine.Planes[order[i]];
960	                var n = planeIdx[0];
961	                var m = planeIdx[1];
962	                mask[m, n] = true;
963	                if (n > 0 && (!mask[m, n - 1] || !mask[n, n - 1]))
964	                    return true;
965	            }
966	            return false;
967	        }
