270	        // Wszystkie tablice są płaskimi strukturami sbyte/int przeznaczonymi dla GPU/SIMD
271	        public unsafe static void GetEulerAnglesPackedKernel(
272	            sbyte[] populationM,       // Płaska tablica SOA [PopSize * n * n * N]
273	            int popId,                 // ID aktualnie przetwarzanego osobnika
274	            int cubeId,                // ID aktualnie przetwarzanego kubika
275	            int n, int N,              // Wymiar n, całkowita liczba kubików N
276	            int[][] planes,            // Definicje płaszczyzn obrotu (statyczne, znane z góry)
277	            int[] order,               // Kolejność płaszczyzn
278	            byte[] outputStateHashes)  // Tablica wyjściowa na unikalne 2-bitowe hashe stanów kubika
279	        {
280	            unchecked
281	            {
282	                // 1. Kopiujemy macierz orientacji tego konkretnego kubika do pamięci lokalnej (rejestrów wątku)
283	                // Maksymalny wymiar n rzadko przekracza 6, więc tablica lokalna n*n zajmie zaledwie 36 bajtów.
284	                // Na GPU ta pamięć wyląduje w błyskawicznych rejestrach (Local Memory).
285	                sbyte* localA = stackalloc sbyte[n * n];
286	                int baseOffset = (popId * n * n * N) + cubeId;
287	
288	                for (int i = 0; i < n; i++)
289	                {
290	                    for (int j = 0; j < n; j++)
291	                    {
292	                        // Pobieramy dane ze struktury SOA do lokalnego bufora roboczego
293	                        localA[i * n + j] = populationM[baseOffset + (i * n * N) + (j * N)];
294	                    }
295	                }
296	
297	                // Zmienna do spakowania unikalnego hasha stanu kubika (zapis po 2 bity na kąt)
298	                ulong packedStateHash = 0;
299	                int bitShift = 0;
300	
301	                int orderCount = order != null ? order.Length : planes.Length;
302	
303	                // 2. Główna pętla rozkładu Givensa
304	                for (int i = 0; i < orderCount; i++)
305	                {
306	                    int planeIdx = order == null ? i : order[i];
307	                    int axis1 = planes[planeIdx][0];
308	                    int axis2 = planes[planeIdx][1];
309	
310	                    // Pobieramy wartości z lokalnej macierzy roboczej
311	                    sbyte a = localA[axis1 * n + axis1];
312	                    sbyte b = localA[axis2 * n + axis1];
313	
314	                    sbyte cosA = 1;
315	                    sbyte sinA = 0;
316	
317	                    // Eliminujemy Math.Sqrt i operacje float. Dla superkostki wartości a i b mówią nam wszystko:
318	                    if (a == 0 && b == 0)
319	                    {
320	                        cosA = 1;
321	                        sinA = 0;
322	                    }
323	                    else
324	                    {
325	                        // Ponieważ a*a + b*b zawsze daje 1 dla poprawnej macierzy orientacji:
326	                        cosA = a;
327	                        sinA = b;
328	
329	                        // Wykonujemy operację A.Rotate bezpośrednio na lokalnej macierzy 8-bitowej.
330	                        // Obracamy tylko wiersze axis1 i axis2
331	                        for (int col = 0; col < n; col++)
332	                        {
333	                            sbyte origA = localA[axis1 * n + col];
334	                            sbyte origB = localA[axis2 * n + col];
335	
336	                            // Zoptymalizowane branchless mnożenie macierzy 8-bitowych
337	                            localA[axis1 * n + col] = (sbyte)(origA * cosA + origB * sinA);
338	                            localA[axis2 * n + col] = (sbyte)(-origA * sinA + origB * cosA);
339	                        }
340	                    }
341	
342	                    // 3. Pakowanie stanu do unikalnego klucza (Twoje 2 bity na stan cosA/sinA)
343	                    // Mapujemy kombinacje (cos, sin) na unikalną wartość 2-bitową (0, 1, 2, 3)
344	                    byte angleCode = 0;
345	                    if (cosA == 1 && sinA == 0) angleCode = 0; // 0 stopni
346	                    if (cosA == 0 && sinA == 1) angleCode = 1; // 90 stopni
347	                    if (cosA == -1 && sinA == 0) angleCode = 2; // 180 stopni
348	                    if (cosA == 0 && sinA == -1) angleCode = 3; // 270 stopni
349	
350	                    // Wstrzykujemy 2 bity do głównego hasha stanu tego kubika
351	                    packedStateHash |= ((ulong)angleCode << bitShift);
352	                    bitShift += 2;
353	                }
354	
355	                // 4. Zapisujemy unikalny stan (hash) kubika do płaskiej tablicy wyjściowej
356	                int outputIdx = (popId * N) + cubeId;
357	                outputStateHashes[outputIdx] = (byte)packedStateHash;
358	            }
359	        }
360	
361	
362	    };
