364	public static class SimpleHypercubeOrientationCoder
365	    {
366	        // Statyczna tablica silni dla szybkiego dostępu (obsługuje wymiary do N=12)
367	        private static int[] Factorials = { 1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880, 3628800, 39916800, 479001600 };
368	
369	        /// <summary>
370	        /// Koduje macierz obrotu do indeksu, zapisując WSZYSTKIE N bitów znaków.
371	        /// </summary>
372	        public static int MatrixToIndex(int[,] matrix)
373	        {
374	            int n = matrix.GetLength(0);
375	
376	            Span<int> permutation = stackalloc int[n];
377	            int signIndex = 0;
378	
379	            // 1. Jednoczesne wyciąganie permutacji i pakowanie WSZYSTKIECH N znaków jako bity
380	            for (int i = 0; i < n; i++)
381	            {
382	                for (int j = 0; j < n; j++)
383	                {
384	                    if (matrix[i, j] != 0)
385	                    {
386	                        permutation[i] = j;
387	                        if (matrix[i, j] > 0)
388	                        {
389	                            signIndex |= (1 << i); // Ustaw bit na 1 dla znaku dodatniego (+)
390	                        }
391	                        break;
392	                    }
393	                }
394	            }
395	
396	            // 2. Indeksowanie permutacji (Kod Lehmera)
397	            int permIndex = 0;
398	            Span<bool> used = stackalloc bool[n];
399	
400	            for (int i = 0; i < n; i++)
401	            {
402	                int currentVal = permutation[i];
403	                int smallerCount = 0;
404	
405	                for (int j = 0; j < currentVal; j++)
406	                {
407	                    if (!used[j]) smallerCount++;
408	                }
409	
410	                permIndex += smallerCount * Factorials[n - 1 - i];
411	                used[currentVal] = true;
412	            }
413	
414	            // 3. Łączenie: Przesuwamy permutację o N bitów (zamiast N-1) i doklejamy znaki
415	            return (permIndex << n) | signIndex;
416	        }
417	
418	        /// <summary>
419	        /// Dekoduje indeks w sposób uproszczony – bez liczenia wyznacznika/parzystości.
420	        /// </summary>
421	        public static int[,] IndexToMatrix(int index, int n)
422	        {
423	            int[,] matrix = new int[n, n];
424	
425	            // Rozdzielenie bitowe na podstawie pełnego wymiaru N
426	            int signMask = (1 << n) - 1;
427	            int signIndex = index & signMask;
428	            int permIndex = (int)((uint)index >> n);
429	
430	            // 1. Odtworzenie permutacji z kodu Lehmera (liniowy krok)
431	            Span<int> permutation = stackalloc int[n];
432	            Span<int> availableCols = stackalloc int[n];
433	            for (int i = 0; i < n; i++) availableCols[i] = i;
434	
435	            int tempPerm = permIndex;
436	            for (int i = 0; i < n; i++)
437	            {
438	                int factVal = Factorials[n - 1 - i];
439	                int choiceIndex = tempPerm / factVal;
440	                tempPerm %= factVal;
441	
442	                permutation[i] = availableCols[choiceIndex];
443	                for (int j = choiceIndex; j < n - 1 - i; j++)
444	                {
445	                    availableCols[j] = availableCols[j + 1];
446	                }
447	            }
448	
449	            // 2. Bezpośrednie wpisanie wartości do macierzy na podstawie bitów znaków
450	            for (int i = 0; i < n; i++)
451	            {
452	                int sign = ((signIndex & (1 << i)) != 0) ? 1 : -1;
453	                matrix[i, permutation[i]] = sign;
454	            }
455	
456	            return matrix;
457	        }
458	    }
459	
460	}
