﻿#define uint unsigned int
#define N 3
#define SIZE 3
#define CUBIES_COUNT 27
#define PLANES_COUNT 3
#define GENERATIONS_COUNT 50
#define GENES_COUNT 32
#define POPULATION_COUNT 1024
#define WINNERS_RATIO 10
#define MUTATION_RATIO 1

struct Specimen {
    uint Fitness;      // floatBitsToUint(fitness_float)
    uint MovesCount;
    uint Moves[GENES_COUNT];
};

struct Move
{
    uint Axis;
    uint Slice;
    uint Plane;
    uint Angle;
};

Move getMove(int code)
{
    uint angle = code & 3u;
    uint plane = (code >> 2u) & 31u;
    uint axis = (code >> 7u) & 7u;
    uint slice = code >> 10u;
    return Move(axis, slice, plane, angle);
}

// 2. CENTRALNY REJESTR BUFORÓW
layout(std430, binding = 0) buffer PopulationBuffer { Specimen Population[]; };
layout(std430, binding = 1) buffer CubiesBuffer { uint Cubies[]; };
layout(std430, binding = 2) buffer FreeMovesBuffer { uint FreeMoves[]; };
layout(std430, binding = 3) buffer SolvedBuffer { uint SolvedCubies[]; };
layout(std430, binding = 4) buffer ActiveBuffer { uint ActiveCubies[]; };
layout(std430, binding = 5) buffer BestResultBuffer { Specimen Best; };
layout(std430, binding = 6) buffer NewPopulationBuffer { Specimen NewPopulation[]; }; // Dla krzyżowania
layout(std140, binding = 7) uniform PlanesBuffer { ivec2 Planes[PLANES_COUNT]; };

// 3. REJESTR LOKACJI UNIFORMÓW
//layout(location = 0) uniform uint N;
//layout(location = 1) uniform uint SIZE;
//layout(location = 2) uniform uint CUBIES_COUNT; // SIZE^N
//layout(location = 3) uniform uint PLANES_COUNT;
layout(location = 0) uniform uint TimeSeed;
//layout(location = 1) uniform uint countSolved;
//layout(location = 2) uniform uint countActive;
layout(location = 1) uniform uint maxStateValue;
layout(location = 2) uniform uint u_Stage;
layout(location = 3) uniform uint u_PassModStage;


uint bitsForCol;
uint bitsPerRow;

void getRow(uint M, uint row, out uint outCol, out int outSign)
{
    uint rowData = (M >> (row * bitsPerRow)) & ((1u << bitsPerRow) - 1u);

    outCol = rowData & ((1u << bitsForCol) - 1u);
    outSign = ((rowData >> bitsForCol) & 1u) == 1u ? -1 : 1;
}

uint setRow(uint M, uint row, uint col, int sign)
{
    uint signBit = (sign == -1) ? 1u : 0u;
    uint rowData = (signBit << bitsForCol) | (col & ((1u << bitsForCol) - 1u));
    uint shift = row * bitsPerRow;
    uint mask = ((1u << bitsPerRow) - 1u) << shift;
    return (M & ~mask) | (rowData << shift);
}

void RotateMatInt(inout uint M, uint axis1, uint axis2, uint angleStep)
{
    // Wyciągamy tylko dwa interesujące nas wiersze, które tworzą płaszczyznę obrotu
    uint col1, col2;
    int sign1, sign2;
    getRow(M, axis1, col1, sign1);
    getRow(M, axis2, col2, sign2);

    if (angleStep == 0)      // 90 stopni w lewo
    {
        M = setRow(M, axis1, col2, -sign2);
        M = setRow(M, axis2, col1, sign1);
    }
    else if (angleStep == 1) // 180 stopni
    {
        M = setRow(M, axis1, col1, -sign1);
        M = setRow(M, axis2, col2, -sign2);
    }
    else if (angleStep == 2) // 270 stopni (90 stopni w prawo)
    {
        M = setRow(M, axis1, col2, sign2);
        M = setRow(M, axis2, col1, -sign1);
    }
}

uint getStartCoordinate(uint cubieID, uint col)
{
    //Wyznaczenie indeksu warstwy (0 do SIZE-1) dla wybranego wymiaru (col)
    if (SIZE == 2) return (cubieID >> col) & 1; // Szybka operacja bitowa dla SIZE = 2
    uint divisor = 1;
    for (uint i = 0; i < col; i++)
        divisor *= SIZE;
    return (cubieID / divisor) % SIZE;
}

uint TurnSingleCubie(uint cubieMatrix, uint cubieID, Move move) {
    uint col;
    int sign;
    getRow(cubieMatrix, move.Axis, col, sign);
    uint startLayerIndex = getStartCoordinate(cubieID, col);
    uint currentLayer = (sign == 1) ? startLayerIndex : (SIZE - 1) - startLayerIndex;
    if (currentLayer == move.Slice) {
        uint axis1 = Planes[move.Plane].x;
        uint axis2 = Planes[move.Plane].y;
        RotateMatInt(cubieMatrix, axis1, axis2, move.Angle);
    }
    return cubieMatrix;
}

float GetActiveCubieError(uint cubieMatrix, float maxClusterState, float max_fA) {
    if (cubieMatrix != 0)
        return (maxClusterState + float(cubieMatrix)) / max_fA;
    return 0.0;
}

