{
    // Determine the layer index (0 to SIZE-1) for the chosen dimension (col)
    if (SIZE == 2) return (cubieID >> col) & 1; // Fast bitwise op for SIZE = 2
    uint divisor = 1;
    for (uint i = 0; i < col; i++)
        divisor *= SIZE;
    return (cubieID / divisor) % SIZE;
}

uint TurnSingleCubie(uint cubieMatrix, uint cubieID, Move move) {
    uint col;
