    getRow(cubieMatrix, move.Axis, col, sign);
    uint startLayerIndex = getStartCoordinate(cubieID, col);
    uint currentLayer = (sign == 1) ? startLayerIndex : (SIZE - 1) - startLayerIndex;
    if (currentLayer == move.Slice) {
