// L1 (Manhattan) distance of a packed orientation matrix from IDENTITY.
// The identity row r encodes (col = r, sign = +); a solved cubie -> 0. The sign lives on the high
// bit of the field, so it is handled separately from the column index: column displacement
// |col - r| plus a +1 penalty when the axis is reflected (otherwise a reflected-but-in-place
// row would read as distance 0 and be mistaken for solved).
uint cubieL1(uint M) {
    uint colMask = (1u << BITS_FOR_COL) - 1u;
    uint dist = 0u;
    for (uint r = 0u; r < uint(N); r++) {
        uint field = (M >> (r * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
        uint col = field & colMask;                  // column index (sign bit masked off)
        dist += (col > r) ? (col - r) : (r - col);   // column displacement
        dist += field >> BITS_FOR_COL;               // sign bit: +1 if the axis is reflected
