75	void getRow(uint M, uint row, out uint outCol, out int outSign)
76	{
77	    uint rowData = (M >> (row * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
78	
79	    outCol = rowData & ((1u << BITS_FOR_COL) - 1u);
80	    outSign = ((rowData >> BITS_FOR_COL) & 1u) == 1u ? -1 : 1;
81	}
82	
83	uint setRow(uint M, uint row, uint col, int sign)
84	{
85	    uint signBit = (sign == -1) ? 1u : 0u;
86	    uint rowData = (signBit << BITS_FOR_COL) | (col & ((1u << BITS_FOR_COL) - 1u));
87	    uint shift = row * BITS_PER_ROW;
88	    uint mask = ((1u << BITS_PER_ROW) - 1u) << shift;
89	    return (M & ~mask) | (rowData << shift);
90	}
91	
92	void RotateMatInt(inout uint M, uint axis1, uint axis2, uint angleStep)
93	{
94	    // Extract only the two rows we care about, which form the rotation plane
95	    uint col1, col2;
96	    int sign1, sign2;
97	    getRow(M, axis1, col1, sign1);
98	    getRow(M, axis2, col2, sign2);
99	
100	    if (angleStep == 0)      // 90 degrees left
101	    {
102	        M = setRow(M, axis1, col2, -sign2);
103	        M = setRow(M, axis2, col1, sign1);
104	    }
105	    else if (angleStep == 1) // 180 degrees
106	    {
107	        M = setRow(M, axis1, col1, -sign1);
108	        M = setRow(M, axis2, col2, -sign2);
109	    }
110	    else if (angleStep == 2) // 270 degrees (90 degrees right)
111	    {
112	        M = setRow(M, axis1, col2, sign2);
113	        M = setRow(M, axis2, col1, -sign1);
114	    }
115	}
116	
117	uint getStartCoordinate(uint cubieID, uint col)
118	{
119	    // Determine the layer index (0 to SIZE-1) for the chosen dimension (col)
120	    if (SIZE == 2) return (cubieID >> col) & 1; // Fast bitwise op for SIZE = 2
121	    uint divisor = 1;
122	    for (uint i = 0; i < col; i++)
123	        divisor *= SIZE;
124	    return (cubieID / divisor) % SIZE;
125	}
126	
127	uint TurnSingleCubie(uint cubieMatrix, uint cubieID, Move move) {
128	    uint col;
129	    int sign;
130	    getRow(cubieMatrix, move.Axis, col, sign);
131	    uint startLayerIndex = getStartCoordinate(cubieID, col);
132	    uint currentLayer = (sign == 1) ? startLayerIndex : (SIZE - 1) - startLayerIndex;
133	    if (currentLayer == move.Slice) {
134	        uint axis1 = Planes[move.Plane].x;
135	        uint axis2 = Planes[move.Plane].y;
136	        RotateMatInt(cubieMatrix, axis1, axis2, move.Angle);
137	    }
138	    return cubieMatrix;
139	}
140	
141	// L1 (Manhattan) distance of a packed orientation matrix from IDENTITY.
142	// The identity row r encodes (col = r, sign = +), i.e. field value r; a solved cubie -> 0. The sign
143	// is kept on the high bit of the field, so a reflected axis differs by 2^BITS_FOR_COL (>= N),
144	// dominating any column displacement (the "largest difference") so distinct orientations do not
145	// collide to the same L1.
146	uint cubieL1(uint M) {
147	    uint dist = 0u;
148	    for (uint r = 0u; r < uint(N); r++) {
149	        uint field = (M >> (r * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
150	        dist += (field > r) ? (field - r) : (r - field);
151	    }
152	    return dist;
153	}
154	
155	float GetActiveCubieError(uint cubieMatrix, float maxClusterState, float max_fA) {
156	    uint d = cubieL1(cubieMatrix);
157	    if (d != 0u)
158	        return (maxClusterState + float(d)) / max_fA;
159	    return 0.0;
160	}

