8	namespace TGL
9	{
10	    // Klasa macierzy w zapisie kolumnowym
11	    public class TMatrix : TVector
12	    {
13	        public int ColsCount;
14	        public int RowsCount;
15	        public TCols Cols;
16	        public int[] DimSizes;
17	        public class TCols
18	        {
19	            public TMatrix M;
20	            public TVector this[int idx]
21	            {
22	                get
23	                {
24	                    TVector result = new TVector(M.RowsCount);
25	                    Array.Copy(M.Data, idx * result.Size, result.Data, 0, result.Size);
26	                    return result;
27	                }
28	                set
29	                {
30	                    Array.Copy(value.Data, 0, M.Data, idx * M.RowsCount, value.Size);
31	                }
32	            }
33	            public void Swap(int i, int j)
34	            {
35	                TVector tmp = M.Cols[i];
36	                M.Cols[i] = M.Cols[j];
37	                M.Cols[j] = tmp;
38	            }
39	            public void Remove(int idx)
40	            {
41	                Array.Copy(M.Data, (idx + 1) * M.RowsCount, M.Data, idx * M.RowsCount, (M.ColsCount - 1 - idx) * M.RowsCount);
42	                M.ColsCount--;
43	                Array.Resize(ref M.Data, M.RowsCount * M.ColsCount);
44	            }
45	        }
46	        public TMatrix(int rowsCount, int colsCount) : base(rowsCount * colsCount)
47	        {
48	            Cols = new TCols();
49	            Cols.M = this;
50	            RowsCount = rowsCount;
51	            ColsCount = colsCount;
52	            DimSizes = new int[] { RowsCount, ColsCount };
53	        }
54	
55	        public int Coords2Index(int[] coords)
56	        {
57	            var index = coords[0];
58	            for (int i = 1; i < coords.Length; i++)
59	                index = index * DimSizes[i] + coords[i];
60	            return index;
61	        }
62	
63	        public TVector Index2Coords(int index)
64	        {
65	            var stride = Size;
66	            var coords = new TVector(DimSizes.Length);
67	            for (int i = 0; i < coords.Size; i++)
68	            {
69	                stride /= DimSizes[i];
70	                var coord = index / stride;
71	                index -= coord * stride;
72	                coords[i] = coord;
73	            }
74	            return coords;
75	        }
76	
77	        public override TVector Clone()
78	        {
79	            TMatrix result = new TMatrix(RowsCount, ColsCount);
80	            result.Assign(this);
81	            return result;
82	        }
83	        public TMatrix Transpose()
84	        {
85	            TMatrix dest = new TMatrix(ColsCount, RowsCount);
86	            for (int i = 0; i < RowsCount; i++)
87	                for (int j = 0; j < ColsCount; j++)
88	                    dest[j, i] = this[i, j];
89	            return dest;
90	        }
91	        public float this[int row, int col]
92	        { 
93	            get { return Data[col * RowsCount + row]; }
94	            set { Data[col * RowsCount + row] = value; }
95	        }
96	        public static TMatrix operator +(TMatrix left, TMatrix right)
97	        { return (TMatrix)((TVector)left + right); }
98	        public static TMatrix operator -(TMatrix left, TMatrix right)
99	        { return (TMatrix)((TVector)left - right); }
100	        public static TMatrix operator *(TMatrix left, float value)
101	        { return (TMatrix)((TVector)left * value); }
102	        public static TMatrix operator *(TMatrix left, TMatrix right)
103	        {
104	            TMatrix dest = new TMatrix(left.RowsCount, right.ColsCount);
105	            for (int i = 0; i < dest.ColsCount; i++)
106	                dest.Cols[i] = left * right.Cols[i];
107	            return dest;
108	        }
109	        public static TVector Mult(TMatrix m, TVector v)
110	        {
111	            TVector dest = new TVector(m.RowsCount);
112	            for (int i = 0; i < m.ColsCount; i++)
113	                if (v[i] != 0)
114	                    dest += m.Cols[i] * v[i];
115	            return dest;
116	        }
117	        public static TVector operator *(TMatrix m, TVector v)
118	        {
119	            TVector dest = new TVector(m.RowsCount);
120	            for (int y = 0; y < m.RowsCount; y++)
121	                for (int x = 0; x < m.ColsCount; x++)
122	                    dest[y] += m[y, x] * v[x];
123	            return dest;
124	        }
125	        //public static TVector operator *(TVector v, TMatrix m)
126	        //{
127	        //    return m.Transpose() * v;
128	        //}
129	        float _Det;
130	        public float Det
131	        {
132	            get
133	            {
134	                var inv = Inv;
135	                return _Det;
136	            }
137	        }
138	        // Metodą eliminacji Gaussa-Jordana znajdujemy wynik mnożenia [dest] przez odwrotność [src]  
139	        //              [result] = [dst] * [src]-1  , czyli
140	        //              [dst] = [result] * [src]
141	        // Mnożąc i dodając do siebie kolumny macierzy [src] (i odpowiednio w [dest]), redukujemy 
142	        // macierz [src] do macierzy jednostkowej. Wówczas zmodyfikowana macierz [dest] 
143	        // będzie taka sama jak szukana macierz [result]. 
144	        // Dla [dst] będącej macierzą jednostkową możemy wyznaczyć odwrotność [src]
145	        public TMatrix Inv
146	        {
147	            get
148	            {
149	                _Det = 1;
150	                TMatrix src = (TMatrix)Clone();
151	                TMatrix dst = new TMatrix(ColsCount, ColsCount);
152	                dst.LoadIdentity();
153	                for (int i = 0; i < src.ColsCount; i++)
154	                {
155	                    int pivot = i;
156	                    for (int j = i + 1; j < src.ColsCount; j++)
157	                        if (Math.Abs(src[i, j]) > Math.Abs(src[i, pivot]))
158	                            pivot = j;
159	                    if (pivot != i)
160	                    {
161	                        _Det = -_Det;
162	                        src.Cols.Swap(i, pivot);
163	                        dst.Cols.Swap(i, pivot);
164	                    }
165	                    var tmp = src[i, i];
166	                    _Det *= tmp;
167	                    src.Cols[i] *= 1 / tmp;
168	                    dst.Cols[i] *= 1 / tmp;
169	                    for (int j = 0; j < src.ColsCount; j++)
170	                    {
171	                        tmp = src[i, j];
172	                        if (j != i && tmp != 0)
173	                        {
174	                            src.Cols[j] -= src.Cols[i] * tmp;
175	                            dst.Cols[j] -= dst.Cols[i] * tmp;
176	                        }
177	                    }
178	                }
179	                return dst;
180	            }
181	        }
182	        public static TVector Cross(params TVector[] bases)
183	        {
184	            var n = bases.Length + 1;
185	            var A = new TMatrix(n, n - 1);
186	            for (int i = 0; i < n - 1; i++)
187	                A.Cols[i] = bases[i];
188	            A = A.Transpose();
189	            var result = new TVector(n);
190	            for (int i = 0; i < n; i++)
191	            {
192	                var B = (TMatrix)A.Clone();
193	                B.Cols.Remove(i);
194	                result[i] = i % 2 == 0 ? B.Det : -B.Det;
