// Packs every cubie's orientation matrix into the shader's uint format:
// per row r, the field is (sign << BITS_FOR_COL) | col, where col is the position of the
// single non-zero entry of row r and sign is its sign. Identity row r -> field r, so a
// solved cubie packs to the identity value and cubieL1 == 0. Axis numbering matches the CPU
// (row/col = CPU axes), consistent with getStartCoordinate after the axis-order fix.
public uint[] PackCubies()
{
    int bitsForCol = TAffine.N <= 4 ? 2 : 3;
    int bitsPerRow = bitsForCol + 1;
    var packed = new uint[Cubies.Length];
    for (int id = 0; id < Cubies.Length; id++)
    {
        uint m = 0;
        for (int row = 0; row < TAffine.N; row++)
            for (int col = 0; col < TAffine.N; col++)
            {
                var v = M[row][col][id];
                if (v != 0)
                {
                    uint sign = v < 0 ? 1u : 0u;
                    uint field = (sign << bitsForCol) | (uint)col;
                    m |= field << (row * bitsPerRow);
                    break;
                }
            }
        packed[id] = m;
    }
    return packed;
}

