public TAffine Transform = new TAffine();
private string Setup;
public static uint InitProgram;
public static uint EvaluateMicroProgram;
public static uint EvaluateMacroProgram;
public static uint SortProgram;
public static uint SelCrossoverProgram;
public static Ssbo[] PopulationBuffer = new Ssbo[2];
public static Ssbo BestBuffer;

public int GetDefineValue(string defineName)
{
    string targetToken = "#define " + defineName;
    using var reader = new StringReader(Setup);
    string line;
    while ((line = reader.ReadLine()) != null)
    {
        line = line.Trim();
        if (line.StartsWith(targetToken, StringComparison.Ordinal))
        {
            string valuePart = line.Substring(targetToken.Length).Trim();
            if (int.TryParse(valuePart, out int result))
                return result;
        }
    }
    return -1;
    //throw new Exception("Could not find " + defineName + " in \"Setup.glsl.c\"");
}
public void SetDefineValue(string defineName, int value)
{
    var oldValue = GetDefineValue(defineName);
    var defineLine = "#define " + defineName + " ";
    Setup = Setup.Replace(defineLine + oldValue, defineLine + value);
}

public void RebuildShaders()
{
    var N = GetDefineValue("N");
    TRubikCube.Size = GetDefineValue("SIZE");
    var populationCount = GetDefineValue("POPULATION_COUNT");
    var genesCount = GetDefineValue("GENES_COUNT");
    TGA<TRubikGenome>.GenerationsCount = GetDefineValue("GENERATIONS_COUNT");
    SetDefineValue("CUBIES_COUNT", (int)Math.Pow(TRubikCube.Size, N));
    TAffine.N = N;
    TChromosome.GenesLength = genesCount;
    TGA<TRubikGenome>.PopulationCount = populationCount;
    var specimenSize = (genesCount + 2) * sizeof(int);
    var populationSize = populationCount * specimenSize;
    for (int i = 0; i < PopulationBuffer.Length; i++)
    {
        var buf = new Ssbo(populationSize);
        OpenGL.BindBuffer(buf.Type, buf.Id);
        OpenGL.BufferData(buf.Type, buf.Size, null, OpenGL.GL_DYNAMIC_COPY);
        PopulationBuffer[i] = buf;
    }
    BestBuffer = new Ssbo(specimenSize);
    OpenGL.BindBuffer(BestBuffer.Type, BestBuffer.Id);
    OpenGL.BufferData(BestBuffer.Type, BestBuffer.Size, null, OpenGL.GL_DYNAMIC_COPY);

    InitProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.Init.glsl.c");
    EvaluateMicroProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.EvaluateMicro.glsl.c");
    EvaluateMacroProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.EvaluateMacro.glsl.c");
    SortProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.Sort.glsl.c");
    SelCrossoverProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.SelCrossover.glsl.c");
}

public IntPtr Handle
{
    get
    {
        if (HRC == IntPtr.Zero)
        {
            HDC = View.CreateGraphics().GetHdc();
            var pfd = Win32.PIXELFORMATDESCRIPTOR.CreateDefault();
            var idx = Win32.ChoosePixelFormat(HDC, &pfd);
            Win32.SetPixelFormat(HDC, idx, &pfd);
            HRC = Win32.wglCreateContext(HDC);
            Win32.wglMakeCurrent(HDC, HRC);

            Setup = ReadManifestText("Resources.Setup.glsl.c");
            Setup = Setup.Replace("#define uint unsigned int", "");
            RebuildShaders();
        }
        return HRC;
    }

