var populationCount = (uint)TGA<TRubikGenome>.PopulationCount;
var evalProgram = RubikCube.Cubies.Length <= 64 ? TGLContext.EvaluateMicroProgram : TGLContext.EvaluateMacroProgram;
int parentSlot = 0; // Wskazuje na aktualny bufor populacji (0 lub 1)
var best = new TRubikGenome();
var bestBuffer = new int[TGLContext.BestBuffer.Size / sizeof(int)];
fixed (int* bestBufPtr = bestBuffer)
{
    // 2. Uruchomienie shadera inicjalizującego
    OpenGL.UseProgram(TGLContext.InitProgram);
    OpenGL.Uniform1i(0, TAffine.N);
    OpenGL.Uniform1i(1, TRubikCube.Size);
    OpenGL.Uniform1i(2, TRubikGenome.GenesLength);
    uint timeSeed = (uint)Random.Shared.Next();
    if (Random.Shared.Next(2) == 0) // Generujemy pełny zakres 32-bitowy uint
        timeSeed |= 0x80000000; // Losowo ustawiamy najwyższy bit
    OpenGL.Uniform1ui(3, timeSeed);
    var numGroupsX = (uint)(TGLContext.PopulationBuffer[0].Size + 63) / 64;
    OpenGL.DispatchCompute(numGroupsX, 1, 1);
    OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
    //var maxUnFitness = ulong.MaxValue;
    for (int generation = 0; generation < TGA<TRubikGenome>.GenerationsCount; generation++)
    {
        var buf = TGLContext.PopulationBuffer[parentSlot];

        // 1. Ewaluacja (Uruchamia shader micro lub macro)
        OpenGL.UseProgram(evalProgram);
        OpenGL.BindBufferBase(buf.Type, 0, buf.Id);
        OpenGL.Uniform1ui(0, timeSeed++); // Zmiana ziarna losowości
        OpenGL.DispatchCompute(numGroupsX, 1, 1);
        OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
        // 2. Sortowanie Bitoniczne
        OpenGL.UseProgram(TGLContext.SortProgram);
        for (uint stage = 2; stage <= populationCount; stage <<= 1)
        {
            OpenGL.Uniform1ui(6, stage);
            for (uint passModStage = stage >> 1; passModStage > 0; passModStage >>= 1)
            {
                OpenGL.Uniform1ui(7, passModStage);
                OpenGL.DispatchCompute(populationCount / 256, 1, 1);
                OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
            }
        }

        buf = TGLContext.BestBuffer;
        OpenGL.BindBuffer(buf.Type, buf.Id);
        OpenGL.GetBufferSubData(buf.Type, 0, buf.Size, bestBufPtr);
        if (bestBuffer[0] < best.Fitness)
        {
            best.ReadBuffer(bestBuffer);
            if (best.Fitness < RubikCube.Score)
                break;
        }

        // 2. Krzyżowanie i selekcja
        OpenGL.UseProgram(TGLContext.SelCrossoverProgram);
        OpenGL.Uniform1ui(0, timeSeed++);
        OpenGL.DispatchCompute(numGroupsX, 1, 1);
        OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);

        // Przypisujemy rodziców pod slot 0, a dzieci pod slot 5 zgodnie z nagłówkiem shared.glsl
        OpenGL.BindBufferBase(buf.Type, 0, TGLContext.PopulationBuffer[parentSlot].Id);
        OpenGL.BindBufferBase(buf.Type, 5, TGLContext.PopulationBuffer[parentSlot ^ 1].Id);
        OpenGL.Uniform1ui(13, (uint)Environment.TickCount);

        // KROK 4: Ping-Pong (Dzieci stają się rodzicami w następnej iteracji)
        parentSlot ^= 1;

    }
}
return best;

