using System;
using RubikCube;
using TGL;

// CPU reference harness: re-implements the compute-shader core (Setup.glsl.c) in C# and
// cross-checks it against the trusted CPU model (TRubikCube.Turn via VisualTurn, TCubie.State).
class Verify
{
    static int N, SIZE, BFC, BPR;
    static int[][] Planes;

    static (uint col, int sign) GetRow(uint M, int row)
    {
        uint rowData = (M >> (row * BPR)) & ((1u << BPR) - 1u);
        uint col = rowData & ((1u << BFC) - 1u);
        int sign = ((rowData >> BFC) & 1u) == 1u ? -1 : 1;
        return (col, sign);
    }
    static uint SetRow(uint M, int row, uint col, int sign)
    {
        uint signBit = sign == -1 ? 1u : 0u;
        uint rowData = (signBit << BFC) | (col & ((1u << BFC) - 1u));
        int shift = row * BPR;
        uint mask = ((1u << BPR) - 1u) << shift;
        return (M & ~mask) | (rowData << shift);
    }
    static uint RotateMatInt(uint M, int a1, int a2, int step)
    {
        var (c1, s1) = GetRow(M, a1);
        var (c2, s2) = GetRow(M, a2);
        if (step == 0) { M = SetRow(M, a1, c2, -s2); M = SetRow(M, a2, c1, s1); }
        else if (step == 1) { M = SetRow(M, a1, c1, -s1); M = SetRow(M, a2, c2, -s2); }
        else if (step == 2) { M = SetRow(M, a1, c2, s2); M = SetRow(M, a2, c1, -s1); }
        return M;
    }
    static int GetStartCoordinate(int id, int col)
    {
        int shift = N - 1 - col, div = 1;
        for (int i = 0; i < shift; i++) div *= SIZE;
        return (id / div) % SIZE;
    }
    static uint TurnSingleCubie(uint m, int id, int axis, int plane, int slice, int angle)
    {
        var (col, sign) = GetRow(m, axis);
        int startLayer = GetStartCoordinate(id, (int)col);
        int currentLayer = sign == 1 ? startLayer : (SIZE - 1 - startLayer);
        if (currentLayer == slice)
            m = RotateMatInt(m, Planes[plane][0], Planes[plane][1], angle);
        return m;
    }
    static int CubieL1(uint M)
    {
        int dist = 0;
        for (int r = 0; r < N; r++)
        {
            uint field = (M >> (r * BPR)) & ((1u << BPR) - 1u);
            dist += (int)(field > (uint)r ? field - (uint)r : (uint)r - field);
        }
        return dist;
    }

    static void Main()
    {
        N = TAffine.N; SIZE = TRubikCube.Size; BFC = N <= 4 ? 2 : 3; BPR = BFC + 1;
        Planes = TAffine.Planes;
        Console.WriteLine($"N={N} SIZE={SIZE} BITS_FOR_COL={BFC} BITS_PER_ROW={BPR} Planes={Planes.Length}");

        var cube = new TRubikCube();
        int n = cube.Cubies.Length;

        // Shader-side state: start from packed identity for every cubie.
        uint[] port = new uint[n];
        for (int id = 0; id < n; id++)
        {
            uint m = 0;
            for (int r = 0; r < N; r++) m |= (uint)r << (r * BPR);
            port[id] = m;
        }

        // Sanity: packed identity must equal PackCubies() of the freshly-built (solved) cube.
        var solvedTruth = cube.PackCubies();
        int idMism = 0;
        for (int id = 0; id < n; id++) if (port[id] != solvedTruth[id]) idMism++;
        Console.WriteLine($"identity pack mismatches: {idMism}/{n}");

        // Apply the same 100 random moves to both models.
        var rnd = new Random(12345);
        for (int k = 0; k < 100; k++)
        {
            int plane = rnd.Next(Planes.Length);
            int axis; do { axis = rnd.Next(N); } while (axis == Planes[plane][0] || axis == Planes[plane][1]);
            int slice = rnd.Next(SIZE);
            int angle = rnd.Next(3);
            var move = new TMove { Axis = axis, Plane = plane, Slice = slice, Angle = angle };
            var d = TMove.Decode(move.Encode());          // exercise the encode/decode path too
            for (int id = 0; id < n; id++)
                port[id] = TurnSingleCubie(port[id], id, d.Axis, d.Plane, d.Slice, d.Angle);
            cube.VisualTurn(move);
        }

        // 1) Shader turn logic vs CPU orientation matrices.
        var truth = cube.PackCubies();
        int turnMism = 0;
        for (int id = 0; id < n; id++) if (port[id] != truth[id]) turnMism++;
        Console.WriteLine($"turn mismatches (port vs CPU M): {turnMism}/{n}");

        // 2) L1 solved-detection vs the Transform-based State.
        int l1Mism = 0, scrambled = 0;
        for (int id = 0; id < n; id++)
        {
            bool byL1 = CubieL1(truth[id]) == 0;
            bool byState = cube.Cubies[id].State == 0;
            if (!byState) scrambled++;
            if (byL1 != byState) l1Mism++;
        }
        Console.WriteLine($"scrambled cubies: {scrambled}/{n}");
        Console.WriteLine($"L1==0 vs State==0 mismatches: {l1Mism}/{n}");

        Console.WriteLine((idMism == 0 && turnMism == 0 && l1Mism == 0) ? "VERIFY: PASS" : "VERIFY: FAIL");
    }
}

