// in creation order (must match the layout(binding = ...) declarations in Setup.glsl.c).
public static void ResetBinding() => Binding = 0;

public Ssbo(int size, void* data = null, uint type = OpenGL.GL_SHADER_STORAGE_BUFFER)
{
    Size = size;
    Type = type;
    Index = Binding++;
    uint id;
    OpenGL.GenBuffers(1, &id);
    Id = id;
    OpenGL.BindBuffer(Type, Id);
