// Ssbo binding counter yields 0..6 in the exact order the Setup.glsl.c layout expects:
// 0 Population, 1 NewPopulation, 2 Cubies, 3 FreeMoves, 4 SolvedCubies, 5 ActiveCubies,
// 6 Planes (UBO). Per-run inputs (Cubies/FreeMoves/Solved/Active) are uploaded here because
// their contents and sizes change with the cluster being solved.
public static unsafe void CreateBuffers(TRubikCube cube, List<int> freeMoves)
{
    // Keep the shader in sync with the cube: N/SIZE are compile-time defines, so recompile
    // when the dimension or size changed, otherwise the shader reads Cubies out of bounds.
    if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
        Current.RebuildShaders();
    //if (Buffers.Count > 0)
    //{
    //    var ids = Buffers.Select(b => b.Id).ToArray();
    //    fixed (uint* p = ids)
    //        OpenGL.DeleteBuffers(ids.Length, p);
    //    Buffers.Clear();
    //}
    Ssbo.ResetBinding();

    var populationSize = TGA<TRubikGenome>.PopulationCount * (TChromosome.GenesLength + 2) * sizeof(int);
    PopulationBuffer[0] = new Ssbo(populationSize);                                 // binding 0
    PopulationBuffer[1] = new Ssbo(populationSize);                                 // binding 1

    var cubies = cube.PackCubies();
    fixed (uint* p = cubies)
        CubiesBuffer = new Ssbo(cubies.Length * sizeof(uint), p);                  // binding 2

    var moves = freeMoves.ToArray();
    fixed (int* p = moves)
        FreeMovesBuffer = new Ssbo(moves.Length * sizeof(int), p);                 // binding 3

    // Pad empty index arrays to one element so we never create a zero-size SSBO (unreliable
    // .length() / binding). The countSolved / countActive uniforms gate the loops, so the
    // dummy element is never read.
    var solved = cube.SolvedCubies.Select(c => c.StartIndex).ToArray();
    if (solved.Length == 0) solved = new int[1];
    fixed (int* p = solved)
        SolvedBuffer = new Ssbo(solved.Length * sizeof(int), p);                   // binding 4

    var active = cube.ActiveCluster.Select(c => c.StartIndex).ToArray();
    if (active.Length == 0) active = new int[1];
    fixed (int* p = active)
        ActiveBuffer = new Ssbo(active.Length * sizeof(int), p);                   // binding 5

    // std140 array of ivec2: each element is padded to 16 bytes (vec4 alignment).
    var planes = new int[TAffine.Planes.Length * 4];
    for (int i = 0; i < TAffine.Planes.Length; i++)
    {
        planes[4 * i] = TAffine.Planes[i][0];
        planes[4 * i + 1] = TAffine.Planes[i][1];
    }
    fixed (int* p = planes)
        PlanesBuffer = new Ssbo(planes.Length * sizeof(int), p, OpenGL.GL_UNIFORM_BUFFER); // binding 6

    Buffers.Add(PopulationBuffer[0]); Buffers.Add(PopulationBuffer[1]);

