// N and SIZE come from the current cube and are injected as compile-time defines (the shader
// arrays are sized by them), so the shader always matches the cube. Population / genes /
// generations stay as authored in Setup.glsl.c.
public static void RebuildShaders()
{
    SetDefineValue("N", TAffine.N);
    SetDefineValue("SIZE", TRubikCube.Size);
    SetDefineValue("CUBIES_COUNT", (int)Math.Pow(TRubikCube.Size, TAffine.N));
    TChromosome.GenesLength = GetDefineValue("GENES_COUNT");
    TGA<TRubikGenome>.PopulationCount = GetDefineValue("POPULATION_COUNT");
    TGA<TRubikGenome>.GenerationsCount = GetDefineValue("GENERATIONS_COUNT");
    CompiledN = TAffine.N;
    CompiledSize = TRubikCube.Size;

    InitProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.Init.glsl.c");
    EvaluateMicroProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.EvaluateMicro.glsl.c");
    EvaluateMacroProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.EvaluateMacro.glsl.c");
    SortProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.Sort.glsl.c");
