    TGA<TRubikGenome>.GenerationsCount = GetDefineValue("GENERATIONS_COUNT");
    CompiledN = TAffine.N;
    CompiledSize = TRubikCube.Size;

    InitProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.Init.glsl.c");
    EvaluateMicroProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.EvaluateMicro.glsl.c");
    EvaluateMacroProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.EvaluateMacro.glsl.c");
    SortProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.Sort.glsl.c");
    SelCrossoverProgram = CreateProgram(OpenGL.GL_COMPUTE_SHADER, "Resources.SelCrossover.glsl.c");

    // Create the buffers once, in binding order (0..6 as declared in Setup.glsl.c). The
    // constructor only reserves the id + store; CreateBuffers uploads the data every run via
    // Update. The three per-run buffers start as placeholders - their first Update sets the
    // real size (a cluster's move / index counts are known only at run time).
    if (PopulationBuffer[0] == null)
    {
        var populationSize = TGA<TRubikGenome>.PopulationCount * (TChromosome.GenesLength + 2) * sizeof(int);
        var planesCount = TAffine.N * (TAffine.N - 1) / 2;   // PLANES_COUNT
        Ssbo.ResetBinding();
        PopulationBuffer[0] = new Ssbo(populationSize);                                       // 0
        PopulationBuffer[1] = new Ssbo(populationSize);                                       // 1
        CubiesBuffer    = new Ssbo(cubiesCount * sizeof(uint));                               // 2
        FreeMovesBuffer = new Ssbo(sizeof(int));                                              // 3  sized per run
        SolvedBuffer    = new Ssbo(sizeof(int));                                              // 4  sized per run
        ActiveBuffer    = new Ssbo(sizeof(int));                                              // 5  sized per run
        PlanesBuffer    = new Ssbo(planesCount * 4 * sizeof(int), OpenGL.GL_UNIFORM_BUFFER);  // 6  std140
    }
}

