15	    public static unsafe class Gpu
16	    {
17	        public static uint InitProgram, EvaluateMicroProgram, EvaluateMacroProgram, SortProgram, SelCrossoverProgram;
18	        public static Ssbo[] PopulationBuffer = new Ssbo[2];
19	        public static Ssbo CubiesBuffer, FreeMovesBuffer, SolvedBuffer, ActiveBuffer, PlanesBuffer;
20	        static string Setup;
21	        static int CompiledN, CompiledSize;
22	
23	        // Reads the shader source and builds the compute programs. Call once with a current GL context.
24	        public static void Init()
25	        {
26	            Setup = ReadManifestText("Resources.Setup.glsl.c");
27	            Setup = Setup.Replace("#define uint unsigned int", "");
28	            BuildShaders();
29	        }
30	
31	        static int GetDefineValue(string defineName)
32	        {
33	            string targetToken = "#define " + defineName;
34	            using var reader = new StringReader(Setup);
35	            string line;
36	            while ((line = reader.ReadLine()) != null)
37	            {
38	                line = line.Trim();
39	                if (line.StartsWith(targetToken, StringComparison.Ordinal))
40	                {
41	                    string valuePart = line.Substring(targetToken.Length).Trim();
42	                    if (int.TryParse(valuePart, out int result))
43	                        return result;
44	                }
45	            }
46	            return -1;
47	        }
48	
49	        static void SetDefineValue(string defineName, int value)
50	        {
51	            var oldValue = GetDefineValue(defineName);
52	            var defineLine = "#define " + defineName + " ";
53	            Setup = Setup.Replace(defineLine + oldValue, defineLine + value);
54	        }
