122	        static void CompileProgram(uint program, string dotPath)
123	        {
124	            uint shader;
125	            int count;
126	            OpenGL.GetAttachedShaders(program, 1, &count, &shader);
127	            var code = ReadManifestText(dotPath).Replace("#include \"Setup.glsl.c\"", Setup);
128	            OpenGL.ShaderSource(shader, code);
129	            OpenGL.CompileShader(shader);
130	            int status;
131	            OpenGL.GetShaderiv(shader, OpenGL.GL_COMPILE_STATUS, &status);
132	            if (status == 0)
133	                throw new Exception(OpenGL.GetShaderInfoLog(shader));
134	            OpenGL.LinkProgram(program);
135	        }
136	
137	        // Uploads the per-run data into the buffers reserved in Init (0 Population, 1 NewPopulation,
138	        // 2 Cubies, 3 FreeMoves, 4 SolvedCubies, 5 ActiveCubies, 6 Planes UBO). Update reuses the same
139	        // ids/bindings and resizes the store as needed, so there is no buffer churn between GA runs.
140	        public static void CreateBuffers(TRubikCube cube, List<int> freeMoves)
141	        {
142	            // Keep the shader in sync with the cube: N/SIZE are compile-time defines, so recompile
143	            // when the dimension or size changed, otherwise the shader reads Cubies out of bounds.
144	            if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
145	                BuildShaders();
146	            var populationSize = TGA<TRubikGenome>.PopulationCount * (TChromosome.GenesLength + 2) * sizeof(int);
147	            var cubies = cube.PackCubies();
148	            var moves = freeMoves.ToArray();
149	            // Pad empty index arrays to one element so we never make a zero-size SSBO (unreliable
150	            // .length() / binding). The countSolved / countActive uniforms gate the loops.
151	            var solved = cube.SolvedCubies.Select(c => c.StartIndex).ToArray();
152	            if (solved.Length == 0) solved = new int[1];
153	            var active = cube.ActiveCluster.Select(c => c.StartIndex).ToArray();
154	            if (active.Length == 0) active = new int[1];
155	            // std140 array of ivec2: each element is padded to 16 bytes (vec4 alignment).
156	            var planes = new int[TAffine.Planes.Length * 4];
157	            for (int i = 0; i < TAffine.Planes.Length; i++)
158	            {
159	                planes[4 * i] = TAffine.Planes[i][0];
160	                planes[4 * i + 1] = TAffine.Planes[i][1];
161	            }
162	
163	            PopulationBuffer[0].Update(populationSize, null);
164	            PopulationBuffer[1].Update(populationSize, null);
165	            fixed (uint* p = cubies) CubiesBuffer.Update(cubies.Length * sizeof(uint), p);
166	            fixed (int* p = moves) FreeMovesBuffer.Update(moves.Length * sizeof(int), p);
167	            fixed (int* p = solved) SolvedBuffer.Update(solved.Length * sizeof(int), p);
168	            fixed (int* p = active) ActiveBuffer.Update(active.Length * sizeof(int), p);
169	            fixed (int* p = planes) PlanesBuffer.Update(planes.Length * sizeof(int), p);
170	        }
171	
172	        // Runs the genetic algorithm on the GPU for the current cube (TRubikGenome.RubikCube /
173	        // TRubikGenome.FreeMoves) and returns the best specimen found.
174	        public static TRubikGenome ExecuteGA()
175	        {
176	            var cube = TRubikGenome.RubikCube;
177	            var populationCount = (uint)TGA<TRubikGenome>.PopulationCount;
178	            var micro = cube.Cubies.Length <= 64;
179	            var evalProgram = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
180	
181	            // Create + upload all buffers for this run (population, packed cube, free moves, indices, planes).
182	            CreateBuffers(cube, TRubikGenome.FreeMoves);
183	            var solvedCount = (uint)cube.SolvedCubies.Count;
184	            var activeCount = (uint)cube.ActiveCluster.Count;
