1	#version 430
2	#include "Setup.glsl.c"
3	
4	// One thread produces one child specimen via rank selection + crossover.
5	// Parents are read from Population (binding 0), already sorted ascending by fitness
6	// by the bitonic sort. Children are written to NewPopulation (binding 6).
7	layout(local_size_x = 64) in;
8	
9	// Inverse move: keep axis/plane/slice, negate the angle (0<->2, 1 stays). Matches TMove.GetRevCode.
10	uint getRevCode(uint code) {
11	    return (code & ~3u) | (2u - (code & 3u));
12	}
13	
14	void main() {
15	    uint cid = gl_GlobalInvocationID.x;
16	    if (cid >= POPULATION_COUNT) return;
17	
18	    uint seed = cid ^ TimeSeed;
19	
20	    // Rank selection: draw two distinct parents from the top WINNERS_RATIO percent.
21	    uint winnerCount = (POPULATION_COUNT * WINNERS_RATIO) / 100u;
22	    if (winnerCount < 2u) winnerCount = 2u;
23	    uint momIdx = hash(seed + 1u) % winnerCount;
24	    uint dadIdx = (momIdx + 1u + hash(seed + 2u) % (winnerCount - 1u)) % winnerCount;
25	
26	    // Split point in the first half. Mirrors CPU: Rnd.Next(GENES_COUNT) / 2.
27	    uint startPos = (hash(seed + 3u) % GENES_COUNT) / 2u;
28	    uint stopPos = startPos + 1u + hash(seed + 4u) % uint(N - 1);
29	    if (stopPos > GENES_COUNT / 2u) stopPos = GENES_COUNT / 2u;
30	
31	    // 1. Build the first part with a single write per gene (no redundant full-mom copy):
32	    //    mom prefix [0, startPos), then dad's middle [startPos, stopPos).
33	    uint child[GENES_COUNT];
34	    for (uint i = 0u; i < startPos; i++)
35	        child[i] = Population[momIdx].Moves[i];
36	    for (uint i = startPos; i < stopPos; i++)
37	        child[i] = Population[dadIdx].Moves[i];
38	
39	    // 3. mutation with probability MUTATION_RATIO percent: replace one gene in the first part.
40	    if (hash(seed + 5u) % 100u < uint(MUTATION_RATIO)) {
41	        uint mpos = hash(seed + 6u) % stopPos;
42	        child[mpos] = FreeMoves[hash(seed + 7u) % uint(FreeMoves.length())];
43	    }
44	
45	    // 4. second half = reverse-complement of the first part: the mom block [0,startPos)
46	    //    and the dad block [startPos,stopPos), each reversed with negated angles.
47	    uint pos = stopPos;
48	    for (int i = int(startPos) - 1; i >= 0; i--)
49	        child[pos++] = getRevCode(child[i]);
50	    for (int i = int(stopPos) - 1; i >= int(startPos); i--)
51	        child[pos++] = getRevCode(child[i]);
52	
53	    // 5. mom's tail beyond the reversible core [2*stopPos, GENES_COUNT) stays as mom (as on the CPU).
54	    for (uint i = 2u * stopPos; i < GENES_COUNT; i++)
55	        child[i] = Population[momIdx].Moves[i];
56	
