1	using System;
2	using System.Numerics;
3	
4	namespace TGL
5	{
6	    [Serializable]
7	    public class TVector
8	    {
9	        public float[] Data;
10	        public int Size { get { return Data.Length; } }
11	        public TVector(int count = 3)
12	        {
13	            Data = new float[count];
14	        }
15	        public TVector(params float[] data)
16	        {
17	            Data = new float[data.Length];
18	            Array.Copy(data, Data, data.Length);
19	        }
20	        public float this[int idx]
21	        {
22	            get { return Data[idx]; }
23	            set { Data[idx] = value; }
24	        }
25	        public void Assign(TVector src)
26	        {
27	            Array.Copy(src.Data, Data, Size);
28	        }
29	        public void Clear() { Array.Clear(Data, 0, Data.Length); }
30	        public virtual TVector Clone()
31	        {
32	            return new TVector(Data);
33	        }
34	        // Operacje sumowania i mnożenia wektorów oraz przekształcenia odwrotne są tak często używane, 
35	        // że będziemy do tego celu używać operatorów arytmetycznych. Przeciążymy operatory +, -, *, /
36	        public static TVector operator +(TVector left, TVector right)
37	        {
38	            TVector dest = left.Clone();
39	            int i = 0;
40	            //if (Vector.IsHardwareAccelerated)
41	            //{
42	            //    var simdLen = Vector<float>.Count;
43	            //    for (; i <= dest.Size; i += simdLen)
44	            //    {
45	            //        var l = new Vector<float>(left.Data, i);
46	            //        var r = new Vector<float>(right.Data, i);
47	            //        Vector.Add(l, r).CopyTo(dest.Data, i);
48	            //    }
49	            //}
50	            //else
51	                for (; i < dest.Size; i++)
52	                    dest[i] += right[i];
53	            return dest;
54	        }
55	        public static TVector operator -(TVector left, TVector right)
56	        {
57	            TVector dest = left.Clone();
58	            for (int i = 0; i < dest.Size; i++)
59	                dest[i] -= right[i];
60	            return dest;
61	        }
62	        public static TVector operator *(TVector left, TVector right)
63	        {
64	            TVector dest = left.Clone();
65	            for (int i = 0; i < dest.Size; i++)
66	                dest[i] *= right[i];
67	            return dest;
68	        }
69	        public static TVector operator /(TVector left, TVector right)
70	        {
71	            TVector dest = left.Clone();
72	            for (int i = 0; i < dest.Size; i++)
73	                dest[i] /= right[i];
74	            return dest;
75	        }
76	        public static TVector operator +(TVector left, float value)
77	        {
78	            TVector dest = left.Clone();
79	            for (int i = 0; i < dest.Size; i++)
80	                dest[i] += value;
81	            return dest;
82	        }
83	        public static TVector operator -(TVector left, float value)
84	        {
85	            TVector dest = left.Clone();
86	            for (int i = 0; i < dest.Size; i++)
87	                dest[i] -= value;
88	            return dest;
89	        }
90	        public static TVector operator *(TVector left, float value)
91	        {
92	            TVector dest = left.Clone();
93	            for (int i = 0; i < dest.Size; i++)
94	                dest[i] *= value;
95	            return dest;
96	        }
97	        public static TVector operator /(TVector left, float value)
98	        {
99	            TVector dest = left.Clone();
100	            for (int i = 0; i < dest.Size; i++)
101	                dest[i] /= value;
102	            return dest;
103	        }
104	        public float X { get { return Data[0]; } set { Data[0] = (float)value; } }
105	        public float Y { get { return Data[1]; } set { Data[1] = (float)value; } }
106	        public float Z { get { return Data[2]; } set { Data[2] = (float)value; } }
107	        public float W { get { return Data[3]; } set { Data[3] = (float)value; } }
108	        // Zdefiniujemy również przydatne operacje na dwóch wektorach – iloczyn skalarny (dot product) 
109	        // i wektorowy (cross product) oraz property X,Y,Z,W i Norm ułatwiające dostęp do składowych
110	        public float Dot(TVector v)
111	        {
112	            float result = 0;
113	            for (int i = 0; i < Size; i++)
114	                result += this[i] * v[i];
115	            return result;
116	        }
117	        public TVector Cross(TVector v)
118	        {
119	            TVector result = new TVector();
120	            result.X = Y * v.Z - Z * v.Y;
121	            result.Y = Z * v.X - X * v.Z;
122	            result.Z = X * v.Y - Y * v.X;
123	            return result;
124	        }
125	        public double Norm
126	        {
127	            get { return Math.Sqrt(Dot(this)); }
128	            set
129	            {
130	                Assign(this * (float)(value / Norm));
131	            }
132	        }
133	        public TVector Abs()
134	        {
135	            var result = Clone();
136	            for (int i = 0; i < result.Data.Length; i++)
137	                result[i] = Math.Abs(result[i]);
138	            return result;
139	        }
140	        public float Sum()
141	        {
142	            var result = 0f;
143	            for (int i = 0; i < Data.Length; i++)
144	                result += Data[i];
145	            return result;
146	        }
147	        public float Max()
148	        {
149	            var result = float.MinValue;
150	            for (int i = 0; i < Data.Length; i++)
151	                if (Data[i] > result)
152	                    result = Data[i];
153	            return result;
154	        }
155	
156	        public static TVector Uniform(int n)
157	        {
158	            var result = new TVector(n);
159	            for (int i = 0; i < n; i++)
160	                result[i] = i;
161	            return result;
162	        }
163	
164	        public TVector Resample(TVector x, TVector x_)
165	        {
166	            var y_ = new TVector(x_.Size);
167	            var y = this;
168	            x_ = x_ / x_[x_.Size - 1] * x[x.Size - 1];
169	            int j = 1;
170	            for (int i = 0; i < x_.Size; i++)
171	            {
172	                while (x[j] < x_[i]) j++;
173	                var ratio = (x_[i] - x[j - 1]) / (x[j] - x[j - 1]);
174	                y_[i] = y[j - 1] * (1 - ratio) + y[j] * ratio;
175	            }
176	            return y_;
177	        }
