179	        public virtual void Rotate(int axis1, int axis2, float cosA, float sinA)
180	        {
181	            var t1 = Data[axis1];
182	            var t2 = Data[axis2];
183	            Data[axis1] = cosA * t1 - sinA * t2;
184	            Data[axis2] = sinA * t1 + cosA * t2;
185	        }
