# -*- coding: utf-8 -*-
# Does zeroing ABOVE the diagonal (as well as below) enlarge the set of reachable decomposition trees?
import itertools, random
random.seed(7)

def make_planes(N):
    P=[]
    for row in range(1,N):
        for col in range(row):
            P.append((col,row))
    return P

def ident(N): return [[1 if i==j else 0 for j in range(N)] for i in range(N)]

def apply_givens(A,n,m,k):            # left-multiply by 90*k rotation in plane (n,m)
    c=[1,0,-1,0][k]; s=[0,1,0,-1][k]; N=len(A)
    rn=A[n][:]; rm=A[m][:]
    for j in range(N):
        A[n][j]=c*rn[j]-s*rm[j]
        A[m][j]=s*rn[j]+c*rm[j]

def random_M(N,planes,nrot):
    M=ident(N)
    for _ in range(nrot):
        n,m=random.choice(planes); apply_givens(M,n,m,random.choice([1,2,3]))
    return M

def all_active(M):
    return all(M[i][i]!=1 for i in range(len(M)))

def is_diag_pm1(A):
    N=len(A)
    return all(A[i][j]==0 for i in range(N) for j in range(N) if i!=j) and all(abs(A[i][i])==1 for i in range(N))

def reduce_(M, order, modes, planes):
    N=len(M); A=[r[:] for r in M]; tree=set()
    for i in range(len(planes)):
        n,m=planes[order[i]]; mode=modes[i]        # mode 0 = zero below A[m,n], 1 = zero above A[n,m]
        tgt = A[m][n] if mode==0 else A[n][m]
        if tgt==0: continue
        for k in (1,2,3):
            B=[r[:] for r in A]; apply_givens(B,n,m,k)
            if (B[m][n] if mode==0 else B[n][m])==0:
                A=B; tree.add((n,m)); break
    return frozenset(tree), is_diag_pm1(A)

N=4; planes=make_planes(N); P=len(planes)
while True:
    M=random_M(N,planes,3)
    if all_active(M): break
print("N=",N,"planes=",planes); [print("  ",r) for r in M]
print("active axes:", sum(M[i][i]!=1 for i in range(N)), "| Cayley N^(N-2) spanning trees =", N**(N-2))

below=set(); above=set(); mixed=set()
for order in itertools.permutations(range(P)):
    o=list(order)
    t,ok=reduce_(M,o,[0]*P,planes)                 # pure below
    if ok: below.add(t)
    t,ok=reduce_(M,o,[1]*P,planes)                 # pure above
    if ok: above.add(t)
    for modes in itertools.product((0,1),repeat=P): # mixed
        t,ok=reduce_(M,o,list(modes),planes)
        if ok: mixed.add(t)

print("\ntrees reachable:")
print("  below-only        :", len(below))
print("  above-only        :", len(above))
print("  below | above     :", len(below|above))
print("  mixed (up+down)   :", len(mixed))
print("  mixed adds beyond below|above:", sorted(sorted(t) for t in (mixed-(below|above))))

