// Greedy shortest-solve of a random active cubie's orientation: at each step pick a random cube
// move (plane + 90/180/270) that lowers the moves-to-solve (RotationCount) by one, and record it.
// Always reaches identity - a progress move exists on every shortest path, so it is reject-free -
// and the random choices cover every decomposition tree. The axis is deferred (the cubie
// trajectory is axis-independent); coords are recorded before each step so the caller realizes
// each move with any axis. m = active axes.
List<int[]> GetSolveSteps(out int[][] coordAtStep, out int m)
{
    var cube = new TRubikCube(this);
    var freeCubies = new List<TCubie>();
    foreach (var cubie in cube.ActiveCluster)
        if (cubie.State != 0)
            freeCubies.Add(cubie);
    if (freeCubies.Count > 0)
        cube.ActiveCubie = freeCubies[TChromosome.Rnd.Next(freeCubies.Count)];
    var c = cube.ActiveCubie;
    m = c.ActiveAxisCount();

    var steps = new List<int[]>();          // each: { plane, moveAngle }
    var coords = new List<int[]>();
    int cur, guard = 0;
    while ((cur = RotationCount(c.Transform)) > 0 && guard++ < 4 * TAffine.N)
    {
        var cand = new List<int[]>();
        for (int plane = 0; plane < TAffine.Planes.Length; plane++)
            for (int angle = 0; angle < 3; angle++)          // 0/1/2 -> 90/180/270
                if (RotationCountAfter(c, plane, angle) == cur - 1)
                    cand.Add(new[] { plane, angle });
        if (cand.Count == 0) break;                          // only if the rotation convention is off

        var pick = cand[TChromosome.Rnd.Next(cand.Count)];
        int p = pick[0], a = pick[1];

        var coord = new int[TAffine.N];
        for (int ax = 0; ax < TAffine.N; ax++)
            coord[ax] = c.GetPos(ax);
        coords.Add(coord);
        steps.Add(new[] { p, a });

        var pa = TAffine.Planes[p];
        int canon = 0;                       // any axis not in the plane, only to advance the sim
        while (canon == pa[0] || canon == pa[1]) canon++;
        cube.Turn(new TMove { Plane = p, Angle = a, Axis = canon, Slice = coord[canon] });
    }
    coordAtStep = coords.ToArray();
    return steps;
}

// Moves-to-solve (count of non-trivial Givens rotations) of an orientation. Order-invariant.
static int RotationCount(TAffine orientation)
{
    int rc = 0;
    foreach (var rot in orientation.GetEulerAngles(null))
        if (TCubie.GetAngle(rot[0], rot[1]) != 0) rc++;
    return rc;
}

// Moves-to-solve after applying the cube move (plane, angle) to the cubie - the same rotation Turn
// applies - so the greedy's prediction matches the real move (keeping it reject-free).
static int RotationCountAfter(TCubie c, int plane, int angle)
{
    var T = c.Transform.Clone();
    T.Rotate(plane, (angle + 1) * 90);
    return RotationCount(T);
}

