136	    // coords[0]*SIZE^(N-1) + ... + coords[N-1], so axis col has stride SIZE^(N-1-col), i.e. axis 0
137	    // is the most significant digit. This keeps the shader's axis numbering identical to the CPU's.
138	    uint shift = N - 1u - col;
