List<int> GetSolveSteps(out int m)
{
    var cube = new TRubikCube(this);
    // Focus: solve the host-designated active cubie (the same one for the whole GA run; the
    // caller varies it between runs). Map it into the clone by home index; fall back to a random
    // unsolved cubie if none is designated or it is already solved.
    TCubie c = null;
    if (ActiveCubie != null)
        foreach (var x in cube.ActiveCluster)
