    {
        var freeCubies = new List<TCubie>();
        foreach (var x in cube.ActiveCluster)
            if (x.State != 0) freeCubies.Add(x);
        if (freeCubies.Count == 0) { m = 0; return new List<int>(); }
        c = freeCubies[TChromosome.Rnd.Next(freeCubies.Count)];
    }
    cube.ActiveCubie = c;
    m = c.ActiveAxisCount();

