// Greedy shortest-solve of a random active cubie: at each step pick a random cube move (plane +
// 90/180/270) that lowers the moves-to-solve (RotationCount) by one, realize it with a random
// valid axis, record its code and apply it - until the orientation is the identity. Reject-free
// (a progress move exists on every shortest path); random choices cover every decomposition tree.
// The axis only picks the collateral layer, not the target's solve. m = active axes.
List<int> GetSolveSteps(out int m)
{
    var cube = new TRubikCube(this);   // the clone already carries the host-designated ActiveCubie
    var c = cube.ActiveCubie;          // focus: solve it (same for the whole run; the caller varies it between runs)
    m = c.ActiveAxisCount();

    var seq = new List<int>();
    int guard = 0;
    while (c.State != 0 && guard++ < 4 * TAffine.N)          // State getter refreshes c.RotationCount
    {
        int cur = c.RotationCount;
        var cand = new List<int[]>();
        for (int plane = 0; plane < TAffine.Planes.Length; plane++)
            for (int angle = 0; angle < 3; angle++)          // 0/1/2 -> 90/180/270
                if (RotationCountAfter(c, plane, angle) == cur - 1)
                    cand.Add(new[] { plane, angle });
        if (cand.Count == 0) break;                          // only if the rotation convention is off

        var pick = cand[TChromosome.Rnd.Next(cand.Count)];
        var pa = TAffine.Planes[pick[0]];
        int axis = TChromosome.Rnd.Next(TAffine.N);          // any axis not in the plane (collateral only)
        while (axis == pa[0] || axis == pa[1])
            axis = (axis + 1) % TAffine.N;
        var move = new TMove { Plane = pick[0], Angle = pick[1], Axis = axis, Slice = c.GetPos(axis) };
        seq.Add(move.Encode());
        cube.Turn(move);
    }
    return seq;
}

