using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using TGL;

namespace RubikCube
{
    public class TCubie : TShape
    {
        public static TShape Cube;
        public static TMatrix SizeMatrix;
        public static int MaxScore;
        //public double Error;
        public int StartIndex;
        public int RotationCount;
        public static TVector Scaling;
        public bool IsReversedSeq;
        public int ClusterIndex;
        public TVector GivensOrder;

        public TCubie()
        {
            Vertices = Cube.Vertices;
            Faces = Cube.Faces;
            Colors = Cube.Colors;
        }

        public static int GetAngle(double cosA, double sinA)
        {
            if (cosA > 0.5) return 0;
            if (sinA > 0.5) return 1;
            if (cosA < -0.5) return 2;
            if (sinA < -0.5) return 3;
            return 0;
        }
        public static TVector SetAngle(int angle)
        {
            float cosA = 0;
            float sinA = 0;
            switch (angle)
            {
                case 0: cosA = 1; break;
                case 1: sinA = 1; break;
                case 2: cosA = -1; break;
                case 3: sinA = -1; break;
            }
            return new TVector(cosA, sinA);
        }

        public override float Transparency { 
            get { 
                base.Transparency = State != 0 ? 0.1f : 1;
                return base.Transparency;
            } 
        }

        private bool ValidState;
        int state;
        public int State
        {
            get
            {
                if (!ValidState)
                {
                    state = 0;
                    //EulerAngles = Transform.GetEulerAngles(TRubikCube.EulerOrder, TRubikCube.IsEulerOrderReversed);
                    EulerAngles = Transform.GetEulerAngles(null);
                    RotationCount = 0;
                    var shift = (EulerAngles.Count - 1) << 1;
                    for (int i = 0; i < EulerAngles.Count; i++)
                    {
                        var angle = GetAngle(EulerAngles[i].X, EulerAngles[i].Y);
                        state |= angle << shift;
                        shift -= 2;
                        if (angle > 0)
                        {
                            RotationCount++;
                        }
                    }
                    //var RotationCount2 = TAffine.N;
                    //for (int i = 0; i < TAffine.N; i++)
                    //    if (Math.Abs(Transform.M[i, i]) > 0.5)
                    //        RotationCount2--;
                    //RotationCount = RotationCount * TAffine.N + RotationCount2;

                    //state |= RotationCount << 2 * EulerAngles.Count;

                    //var xform = TAffine.CreateScale(new TVector(0.45f, 0.45f, 0.45f, 0.45f));
                    //for (int i = TAffine.Planes.Length - 1; i >= 0; i--)
                    //    xform = TAffine.CreateRotation(i, 90 * (state >> 2 * i & 3)) * xform;
                    //var Error = (xform.M - Transform.M).Norm;
                    //if (Error > 0.01)
                    //    ;                    

                    ValidState = true;
                    //for (int i = 0; i < TAffine.N; i++)
                    //    if (Math.Abs(Transform.M[i, i] - Scaling[i]) > 1E-3)
                    //    {
                    //        state = 1;
                    //        break;
                    //    }
                }
                return state;
            }
            set
            {
                Transform = TAffine.CreateScale(Scaling);
                Index = StartIndex;
                for (int i = TAffine.Planes.Length - 1; i >= 0; i--)
                {
                    var shift = (TAffine.Planes.Length - 1 - i) << 1;
                    Transform.Rotate(i, 90 * (value >> shift & 3));
                }
                ValidState = false;
                var state_ = State;
                if (state_ != value)
                    ;
                state = value;
                ValidState = true;
                //if (state != 0)
                //    Transparency = 0.5f;
            }
        }

        public void Rotate(int[] plane, TVector rot)
        {
            Transform.Rotate(plane[0], plane[1], rot.X, rot.Y);
            ValidState = false;
        }

        // Number of axes the cubie's orientation does not leave fixed: axis k is fixed <=> M[k,k] is
        // the positive scale (~+0.45). Cubies are uniformly scaled, so the threshold sits below it.
        public int ActiveAxisCount()
        {
            int m = 0;
            for (int k = 0; k < TAffine.N; k++)
                if (Transform.M[k, k] < 0.1f) m++;
            return m;
        }

        //public double Score
        //{
        //    get { return (double)State / MaxScore; }
        //}

        //public TVector GetStartPos()
        //{
        //    var cubie = Copy();
        //    for (int axis = 0; axis < TAffine.Planes.Length; axis++)
        //        cubie.Rotate(axis, -90 * (cubie.State >> 2 * axis & 3));
        //    return cubie.Transform.Origin;
        //}

        public TCubie Copy()
        {
            var dest = new TCubie();
            dest.Transform = Transform.Clone();
            dest.Vertices = Vertices;
            dest.Faces = Faces;
            dest.state = state;
            dest.ValidState = ValidState;
            dest.StartIndex = StartIndex;
            dest.RotationCount = RotationCount;
            dest.EulerAngles = EulerAngles;
            return dest;
        }

        public int Index
        {
            get { return SizeMatrix.Coords2Index(Position); }
            set
            {
                var pos = SizeMatrix.Index2Coords(value);
                Transform.Origin = pos - TRubikCube.C;
                var position = new int[pos.Size];
                for (int dim = 0; dim < position.Length; dim++)
                    position[dim] = (int)Math.Round(Math.Abs(Transform.Origin[dim]) + TRubikCube.C);
                Array.Sort(position);
                Array.Reverse(position);
                ClusterIndex = SizeMatrix.Coords2Index(position);
            }
        }

        public int GetPos(int coord) { return (int)Math.Round(Transform.Origin[coord] + TRubikCube.C); }
        public int[] Position
        {
            get 
            {            
                var position = new int[Transform.Origin.Size];
                for (int i = 0; i < position.Length; i++)
                    position[i] = GetPos(i);
                return position;
            }
        }
    }
}

#define uint unsigned int
#define N 3
#define SIZE 3
#define CUBIES_COUNT 27
#define PLANES_COUNT (N*(N-1)/2)
#define GENERATIONS_COUNT 50
#define GENES_COUNT 32
#define POPULATION_COUNT 1024
#define WINNERS_RATIO 10
// Percentage of children rebuilt by macro-mutation (fresh seed + conjugate) in SelCrossover.
// The only mutation operator - single-gene random mutation was removed.
#define MUTATION_RATIO 10
// Percentage of the initial population pre-seeded by Init; the rest are random, for the diversity
// the (incomplete) seed decompositions miss.
#define SEED_RATIO 100

// Row packing of the orientation matrix (N in range [3, 8]): bits for the column index + 1 sign bit.
// Equivalent to findMSB(N-1)+1, but as a compile-time constant (findMSB is not a constant expression).
#define BITS_FOR_COL (N <= 4 ? 2 : 3)
#define BITS_PER_ROW (BITS_FOR_COL + 1)

// Rigorous upper bound on the per-cubie L1 distance.
// This exceeds the achievable maximum, so each active-cluster
// magnitude term stays strictly below 1.
#define MAX_CUBIE_L1 (N * ((1 << BITS_FOR_COL) + N - 1))

// Per-cubie penalty = moves-to-solve (active axes, dominant) * (MAX_CUBIE_L1 + 1) + L1 (tiebreak).
// Rigorous upper bound: m <= N active axes, L1 <= MAX_CUBIE_L1; still exceeds the achievable maximum,
// so each active-cluster magnitude term stays strictly below 1.
#define MAX_CUBIE_STATE (N * (MAX_CUBIE_L1 + 1) + MAX_CUBIE_L1)

// Slot width (in genes) reserved for one Init seed sequence: solving a cubie takes at most N-1 moves.
#define SEED_STRIDE (uint(N) - 1u)

struct Specimen {
    uint Fitness;      // floatBitsToUint(fitness_float)
    uint MovesCount;
    uint Moves[GENES_COUNT];
};

struct Move
{
    uint Axis;
    uint Slice;
    uint Plane;
    uint Angle;
};

Move getMove(uint code)
{
    uint angle = code & 3u;
    uint plane = (code >> 2u) & 31u;
    uint axis = (code >> 7u) & 7u;
    uint slice = code >> 10u;
    return Move(axis, slice, plane, angle);
}

// Fast bitwise hash for randomness generation (shared by Init and SelCrossover)
uint hash(uint x) {
    x = ((x >> 16) ^ x) * 0x45d9f3bu;
    x = ((x >> 16) ^ x) * 0x45d9f3bu;
    x = (x >> 16) ^ x;
    return x;
}

// 2. Central buffer registry
layout(std430, binding = 0) buffer PopulationBuffer { Specimen Population[]; };
layout(std430, binding = 1) buffer NewPopulationBuffer { Specimen NewPopulation[]; }; // Crossover output (ping-pong with Population)
layout(std430, binding = 2) buffer CubiesBuffer { uint Cubies[]; };
layout(std430, binding = 3) buffer FreeMovesBuffer { uint FreeMoves[]; };
layout(std430, binding = 4) buffer SolvedBuffer { uint SolvedCubies[]; };
layout(std430, binding = 5) buffer ActiveBuffer { uint ActiveCubies[]; };
layout(std140, binding = 6) uniform PlanesBuffer { ivec2 Planes[PLANES_COUNT]; };
layout(std430, binding = 7) buffer SeedBuffer { uint SeedMoves[]; };   // Init: per-specimen seed sequences

// 3. Uniform location registry
//layout(location = 0) uniform uint N;
//layout(location = 1) uniform uint SIZE;
//layout(location = 2) uniform uint CUBIES_COUNT; // SIZE^N
//layout(location = 3) uniform uint PLANES_COUNT;
layout(location = 0) uniform uint TimeSeed;
// Cluster sizes come from the host, not buffer .length(): a first cluster has an empty SolvedCubies
// buffer, and .length() on a zero-size SSBO is unreliable across drivers.
layout(location = 4) uniform uint countSolved;
layout(location = 5) uniform uint countActive;
layout(location = 2) uniform uint u_Stage;
layout(location = 3) uniform uint u_PassModStage;
layout(location = 6) uniform uint numSeeds;   // Init: number of specimens pre-seeded from SeedMoves


void getRow(uint M, uint row, out uint outCol, out int outSign)
{
    uint rowData = (M >> (row * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);

    outCol = rowData & ((1u << BITS_FOR_COL) - 1u);
    outSign = ((rowData >> BITS_FOR_COL) & 1u) == 1u ? -1 : 1;
}

uint setRow(uint M, uint row, uint col, int sign)
{
    uint signBit = (sign == -1) ? 1u : 0u;
    uint rowData = (signBit << BITS_FOR_COL) | (col & ((1u << BITS_FOR_COL) - 1u));
    uint shift = row * BITS_PER_ROW;
    uint mask = ((1u << BITS_PER_ROW) - 1u) << shift;
    return (M & ~mask) | (rowData << shift);
}

void RotateMatInt(inout uint M, uint axis1, uint axis2, uint angleStep)
{
    // Extract only the two rows we care about, which form the rotation plane
    uint col1, col2;
    int sign1, sign2;
    getRow(M, axis1, col1, sign1);
    getRow(M, axis2, col2, sign2);

    if (angleStep == 0)      // 90 degrees left
    {
        M = setRow(M, axis1, col2, -sign2);
        M = setRow(M, axis2, col1, sign1);
    }
    else if (angleStep == 1) // 180 degrees
    {
        M = setRow(M, axis1, col1, -sign1);
        M = setRow(M, axis2, col2, -sign2);
    }
    else if (angleStep == 2) // 270 degrees (90 degrees right)
    {
        M = setRow(M, axis1, col2, sign2);
        M = setRow(M, axis2, col1, -sign1);
    }
}

uint getStartCoordinate(uint cubieID, uint col)
{
    // Home coordinate along dimension col. The CPU linear index (TMatrix.Coords2Index) is
    // coords[0]*SIZE^(N-1) + ... + coords[N-1], so axis col has stride SIZE^(N-1-col), i.e. axis 0
    // is the most significant digit. This keeps the shader's axis numbering identical to the CPU's.
    uint shift = N - 1u - col;
    if (SIZE == 2)
        return (cubieID >> shift) & 1u; // Fast bitwise op for SIZE = 2
    else
    {
        uint divisor = 1u;
        for (uint i = 0u; i < shift; i++)
            divisor *= SIZE;
        return (cubieID / divisor) % SIZE;
    }
}

uint TurnSingleCubie(uint cubieMatrix, uint cubieID, Move move) {
    uint col;
    int sign;
    getRow(cubieMatrix, move.Axis, col, sign);
    uint startLayerIndex = getStartCoordinate(cubieID, col);
    uint currentLayer = (sign == 1) ? startLayerIndex : (SIZE - 1) - startLayerIndex;
    if (currentLayer == move.Slice) {
        uint axis1 = Planes[move.Plane].x;
        uint axis2 = Planes[move.Plane].y;
        RotateMatInt(cubieMatrix, axis1, axis2, move.Angle);
    }
    return cubieMatrix;
}

// L1 (Manhattan) distance of a packed orientation matrix from IDENTITY.
// The identity row r encodes (col = r, sign = +), i.e. field value r; a solved cubie -> 0. The sign
// is kept on the high bit of the field, so a reflected axis differs by 2^BITS_FOR_COL (>= N),
// dominating any column displacement (the "largest difference") so distinct orientations do not
// collide to the same L1.
uint cubieL1(uint M) {
    uint dist = 0u;
    for (uint r = 0u; r < uint(N); r++) {
        uint field = (M >> (r * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
        dist += (field > r) ? (field - r) : (r - field);
    }
    return dist;
}

// Number of axes the orientation does not leave fixed (row r != identity value r). A cubie needs
// m - 1 moves to solve (Givens spanning tree of its active axes), so m is a moves-to-solve measure.
uint activeAxes(uint M) {
    uint m = 0u;
    for (uint r = 0u; r < uint(N); r++) {
        uint field = (M >> (r * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
        if (field != r) m++;
    }
    return m;
}

// Per-cubie penalty: moves-to-solve (active axes, dominant) refined by L1 orientation distance.
// 0 <=> solved. m dominates because each active axis is weighted above the whole L1 range, so the
// search minimises the number of moves first, then the orientation distance within that.
uint cubieState(uint M) {
    return activeAxes(M) * (uint(MAX_CUBIE_L1) + 1u) + cubieL1(M);
}

float GetActiveCubieError(uint cubieMatrix, float maxClusterState, float max_fA) {
    uint d = cubieState(cubieMatrix);
    if (d != 0u)
        return (maxClusterState + float(d)) / max_fA;
    return 0.0;
}

# -*- coding: utf-8 -*-
# Definitive: shortest solve sequences to IDENTITY (not just diagonal-pm1). Enumerate all shortest
# paths M -> I in the cube-move graph, collect the plane-sets (trees). This is the true diversity a
# greedy (progress = distance-to-I decreases) can reach.
from collections import deque
import random
random.seed(7)

def make_planes(N):
    P=[]
    for row in range(1,N):
        for col in range(row): P.append((col,row))
    return P
def ident(N): return [[1 if i==j else 0 for j in range(N)] for i in range(N)]
def apply_givens(A,n,m,k):
    c=[1,0,-1,0][k]; s=[0,1,0,-1][k]; N=len(A); rn=A[n][:]; rm=A[m][:]
    for j in range(N):
        A[n][j]=c*rn[j]-s*rm[j]; A[m][j]=s*rn[j]+c*rm[j]
def random_M(N,planes,nrot):
    M=ident(N)
    for _ in range(nrot):
        n,m=random.choice(planes); apply_givens(M,n,m,random.choice([1,2,3]))
    return M
def all_active(M): return all(M[i][i]!=1 for i in range(len(M)))
def key(A): return tuple(x for row in A for x in row)

def moves_of(A, planes):
    for (n,m) in planes:
        for k in (1,2,3):
            B=[r[:] for r in A]; apply_givens(B,n,m,k); yield (n,m), B

def solve_trees(M, planes, N):
    I=ident(N); dist={key(I):0}; dq=deque([I])
    while dq:
        A=dq.popleft(); d=dist[key(A)]
        for _,B in moves_of(A,planes):
            if key(B) not in dist: dist[key(B)]=d+1; dq.append(B)
    D=dist[key(M)]; trees=set()
    def dfs(A,tree):
        if dist[key(A)]==0: trees.add(frozenset(tree)); return
        d=dist[key(A)]
        for pl,B in moves_of(A,planes):
            if dist.get(key(B),9)==d-1: dfs(B, tree|{pl})
    dfs(M, frozenset())
    return D, trees, len(dist)

def m_count(A): return sum(1 for k in range(len(A)) if A[k][k] <= 0)   # non-positive diagonal = ActiveAxisCount

def m_greedy_trees(M, planes):
    trees=set()
    def dfs(A, tree):
        if m_count(A)==0: trees.add(frozenset(tree)); return
        cur=m_count(A)
        for pl,B in moves_of(A,planes):
            if m_count(B)<cur: dfs(B, tree|{pl})
    dfs([r[:] for r in M], frozenset())
    return trees

def any_state_stuck(planes, N):
    # over ALL reachable states: is there a non-identity state with NO m-reducing move?
    I=ident(N); seen={key(I)}; dq=deque([I]); stuck=[]
    while dq:
        A=dq.popleft()
        for _,B in moves_of(A,planes):
            if key(B) not in seen: seen.add(key(B)); dq.append(B)
    bad=0
    for ks in seen:
        A=[[ks[i*N+j] for j in range(N)] for i in range(N)]
        if m_count(A)==0: continue
        cur=m_count(A)
        if not any(m_count(B)<cur for _,B in moves_of(A,planes)): bad+=1
    return bad, len(seen)

N=4; planes=make_planes(N)
random.seed(7)
while True:
    M=random_M(N,planes,3)
    if all_active(M): break
print("M:"); [print("  ",r) for r in M]
D,trees,reach = solve_trees(M,planes,N)
print("reachable signed-perm states (det+1):", reach)
print("shortest solve length D =", D, " | shortest-solve trees:", len(trees))

mg = m_greedy_trees(M, planes)
print("\n--- m-greedy (non-positive diagonal count strictly decreases) ---")
print("m-greedy trees:", len(mg), " | equals shortest-solve set:", mg==trees)
print("m-greedy tree sizes:", sorted(set(len(t) for t in mg)))
print("m-greedy \\ shortest:", sorted(sorted(t) for t in (mg-trees))[:6])
bad,nstates = any_state_stuck(planes, N)
print("STUCK states (non-identity, no m-reducing move):", bad, "/", nstates)

