# -*- coding: utf-8 -*-
# For every shortest-path move (BFS dist decreases by 1), record (drop in m, angle).
# m = activeAxes = #rows with diagonal != +1.  Hypothesis: a move retiring >=2 axes is always 180.
from collections import deque, Counter
import verify_solve_trees as v

def run(N):
    planes=v.make_planes(N)
    def m_of(A): return sum(1 for k in range(N) if A[k][k]!=1)
    def moves_full(A):
        for (i,j) in planes:
            for k in (1,2,3):
                B=[r[:] for r in A]; v.apply_givens(B,i,j,k); yield (i,j),k,B
    ANG={1:'90',2:'180',3:'270'}
    I=v.ident(N); dist={v.key(I):0}; dq=deque([I])
    while dq:
        A=dq.popleft(); d=dist[v.key(A)]
        for _,B in v.moves_of(A,planes):
            kb=v.key(B)
            if kb not in dist: dist[kb]=d+1; dq.append(B)
    tab=Counter()
    for ks,d in dist.items():
        if d==0: continue
        A=[[ks[i*N+j] for j in range(N)] for i in range(N)]
        mA=m_of(A)
        for (i,j),k,B in moves_full(A):
            if dist[v.key(B)]==d-1:
                tab[(mA-m_of(B), ANG[k])]+=1
    print(f"--- N={N}  reachable={len(dist)} ---")
    print(" dropΔm  angle   #shortest-path-moves")
    for key in sorted(tab):
        print(f"   {key[0]:+d}     {key[1]:>4}       {tab[key]}")
    ge2=Counter(); le0=Counter()
    for (dm,ang),c in tab.items():
        if dm>=2: ge2[ang]+=c
        if dm<=0: le0[ang]+=c
    print("  Δm>=2 (retires 2+ axes) by angle:", dict(ge2))
    print("  Δm<=0 (m NOT reduced, yet shortest) by angle:", dict(le0))

