# -*- coding: utf-8 -*-
# GetSolveSeq greedy uses candidates with RotationCountAfter == RotationCount-1 (EXACTLY one).
# Is that reject-free? For every non-identity reachable state, does >=1 such move exist?
# If some state has NONE, the greedy stalls: with the break it returns a PARTIAL (non-solving) seed;
# without it, cand[Rnd.Next(0)] crashes.
import importlib.util
spec=importlib.util.spec_from_file_location("vs","verify_solvedaxis.py")
vs=importlib.util.module_from_spec(spec); spec.loader.exec_module(vs)
from collections import deque

def check(N):
    planes=vs.planes_of(N)
    start=vs.ident(N); seen={vs.key(start)}; dq=deque([start]); states=[start]
    while dq:
        A=dq.popleft()
        for (i,j) in planes:
            for (c,s) in [(0,1),(-1,0),(0,-1)]:
                B=vs.move(A,i,j,c,s); k=vs.key(B)
                if k not in seen: seen.add(k); dq.append(B); states.append(B)
    stuck=[]; maxlen=0
    for M in states:
        R0=vs.rotcount(M,planes)
        if R0==0: continue
        has_minus1=False; best=None
        for (i,j) in planes:
            for (c,s) in [(0,1),(-1,0),(0,-1)]:
                R1=vs.rotcount(vs.move(M,i,j,c,s),planes)
                if R1==R0-1: has_minus1=True
        maxlen=max(maxlen,R0)
        if not has_minus1: stuck.append((M,R0))
    print(f"N={N}: reachable states={len(states)}  maxRotationCount={maxlen}  "
          f"STUCK (no exactly-minus-1 move) = {len(stuck)}")
    for M,R0 in stuck[:4]:
        # show what reductions ARE available
        reds=set()
        for (i,j) in planes:
            for (c,s) in [(0,1),(-1,0),(0,-1)]:
                reds.add(R0 - vs.rotcount(vs.move(M,i,j,c,s),planes))
        print("   stuck M diag=", [M[k][k] for k in range(N)], " R0=",R0," available deltaR=",sorted(reds,reverse=True))

