# -*- coding: utf-8 -*-
import importlib.util, random
from collections import deque, Counter
def load(n,f):
    m=importlib.util.module_from_spec(importlib.util.spec_from_file_location(n,f))
    importlib.util.spec_from_file_location(n,f).loader.exec_module(m); return m
v=load("v","verify_solve_trees.py"); rcm=load("rc","verify_solvedaxis.py")
N=4; planes=v.make_planes(N)
random.seed(7)
while True:
    M=v.random_M(N,planes,3)
    if v.all_active(M): break
def moves_full(A):
    for (i,j) in planes:
        for k in (1,2,3):
            B=[r[:] for r in A]; v.apply_givens(B,i,j,k); yield (i,j),k,B

I=v.ident(N); dist={v.key(I):0}; dq=deque([I]); allst=[I]
while dq:
    A=dq.popleft(); d=dist[v.key(A)]
    for _,B in v.moves_of(A,planes):
        if v.key(B) not in dist: dist[v.key(B)]=d+1; dq.append(B); allst.append(B)
# memoize rotcount and m per state key
ROT={}; MC={}
for A in allst:
    ROT[v.key(A)]=rcm.rotcount(A,planes)
    MC[v.key(A)]=sum(1 for k in range(N) if A[k][k]!=1)

sets_=set(); ordered=set()
def dfs(A,seq):
    if dist[v.key(A)]==0: sets_.add(frozenset(seq)); ordered.add(tuple(seq)); return
    d=dist[v.key(A)]
    for pl,k,B in moves_full(A):
        if dist[v.key(B)]==d-1: dfs(B,seq+[pl])
dfs(M,[])
print(f"M RotationCount={ROT[v.key(M)]}  D={dist[v.key(M)]}  m={MC[v.key(M)]}")
print(f"shortest-solve: ordered={len(ordered)}  sets={len(sets_)}")

def greedy(metric):
    A=[r[:] for r in M]; seq=[]
    while True:
        ka=v.key(A); cur=ROT[ka] if metric=='rot' else MC[ka]
        if cur==0: break
        opts=[(pl,B) for pl,k,B in moves_full(A)
              if (ROT[v.key(B)]==cur-1 if metric=='rot' else MC[v.key(B)]<cur)]
        if not opts: return None
        pl,B=random.choice(opts); seq.append(pl); A=B
    return tuple(seq)

for metric in ('rot','m'):
    random.seed(1); os=set(); ss=set(); lens=Counter()
    for _ in range(8000):
        r=greedy(metric)
        if r is None: continue
        os.add(r); ss.add(frozenset(r)); lens[len(r)]+=1
    tag='RotationCount-greedy (==cur-1)' if metric=='rot' else 'm-greedy (m strictly decreases)'
    print(f"\n{tag}:  ordered={len(os)}/{len(ordered)}  sets={len(ss)}/{len(sets_)}"
          f"  subset_of_shortest={os<=ordered}  lengths={dict(sorted(lens.items()))}")
