# -*- coding: utf-8 -*-
# Self-contained 2^4 model. Build a library of support-4 commutators (scaffold-safe, touch 4 slots).
# From endgame states, how often can we find one that reduces the unsolved-cubie count?
import random, itertools
from collections import Counter
N=4; SIZE=2
planes=[(c,r) for r in range(1,N) for c in range(r)]
def ident(): return [[1 if i==j else 0 for j in range(N)] for i in range(N)]
CS=[[1,0,-1,0],[0,1,0,-1]]
def cs(a): k=a+1; return CS[0][k],CS[1][k]
def rot_orient(O,pl,a):
    i,j=pl; c,s=cs(a); B=[r[:] for r in O]
    B[i]=[c*x-s*y for x,y in zip(O[i],O[j])]; B[j]=[s*x+c*y for x,y in zip(O[i],O[j])]; return B
CEN=(SIZE-1)/2.0
def rot_pos(P,pl,a):
    i,j=pl; c,s=cs(a); p=[x-CEN for x in P]; q=p[:]
    q[i]=c*p[i]-s*p[j]; q[j]=s*p[i]+c*p[j]; return [int(round(x+CEN)) for x in q]
HOMES=[list(t) for t in itertools.product(range(SIZE),repeat=N)]
def solved_cube(): return {tuple(h):(h[:],ident()) for h in HOMES}
def apply_move(cube,mv):
    pl,a,ax,sl=mv
    for home,(pos,O) in list(cube.items()):
        if pos[ax]==sl: cube[home]=(rot_pos(pos,pl,a),rot_orient(O,pl,a))
def apply_seq(cube,seq):
    for mv in seq: apply_move(cube,mv)
def inv_move(mv): pl,a,ax,sl=mv; return (pl,{0:2,1:1,2:0}[a],ax,sl)
def inv_seq(seq): return [inv_move(m) for m in reversed(seq)]
I=ident()
def unsolved(cube): return sum(1 for h,(p,O) in cube.items() if p!=list(h) or O!=I)
def support_seq(seq):
    cube=solved_cube(); apply_seq(cube,seq); return unsolved(cube)
SINGLE=[(pl,a,ax,sl) for pl in planes for a in (0,1,2) for ax in range(N) for sl in (0,1)]
def comm(X,Y): return X+Y+inv_seq(X)+inv_seq(Y)

random.seed(0)
# 1) library of support-4 commutators
LIB=[]
while len(LIB)<200:
    X=[random.choice(SINGLE)]; Y=[random.choice(SINGLE)]
    seq=comm(X,Y)
    if support_seq(seq)==4: LIB.append(seq)
print("support-4 commutator library size:", len(LIB))

# 2) endgame states: apply a few random library ops to solved
def endgame_state(k):
    cube=solved_cube()
    for _ in range(k): apply_seq(cube, random.choice(LIB))
    return cube
def clone(cube): return {h:(p[:],[r[:] for r in O]) for h,(p,O) in cube.items()}

improved=0; deltas=Counter(); trials=200
for _ in range(trials):
    st=endgame_state(random.choice([2,3]))
    u0=unsolved(st)
    if u0==0: continue
    best=0
    for seq in LIB:
        c=clone(st); apply_seq(c,seq); d=unsolved(c)-u0
        if d<best: best=d
    deltas[best]+=1
    if best<0: improved+=1
print(f"endgame states tested: {trials}, with an improving support-4 op: {improved} ({round(improved/trials*100)}%)")
print("best-delta distribution (negative = fewer unsolved):", dict(sorted(deltas.items())))
