27	        // One-time GPU setup: reserve the buffers, create the program + shader objects (attached but
28	        // not yet compiled), then compile them for the current cube. Call once with a current GL context.
29	        public static void Init()
30	        {
31	            Setup = ReadManifestText("Resources.Setup.glsl.c");
32	            Setup = Setup.Replace("#define uint unsigned int", "");
33	
34	            // Reserve the buffers once, in binding order (0..7 as declared in Setup.glsl.c). The
35	            // constructor only reserves id + binding; CreateBuffers sizes and fills them per run via Update.
36	            Ssbo.ResetBinding();
37	            PopulationBuffer[0] = new Ssbo();                       // 0
38	            PopulationBuffer[1] = new Ssbo();                       // 1
39	            CubiesBuffer    = new Ssbo();                           // 2
40	            FreeMovesBuffer = new Ssbo();                           // 3
41	            SolvedBuffer    = new Ssbo();                           // 4
42	            ActiveBuffer    = new Ssbo();                           // 5
43	            PlanesBuffer    = new Ssbo(OpenGL.GL_UNIFORM_BUFFER);   // 6  std140 UBO
44	            SeedMovesBuffer = new Ssbo();                           // 7  Init seed sequences
45	
46	            // Create the program + shader objects once and attach them. BuildShaders only (re)sources,
47	            // compiles and links these same objects, so nothing is ever created or deleted again.
48	            InitProgram = CreateProgram();
49	            EvaluateMicroProgram = CreateProgram();
50	            EvaluateMacroProgram = CreateProgram();
51	            SortProgram = CreateProgram();
52	            SelCrossoverProgram = CreateProgram();
53	
54	            BuildShaders();
55	        }
56	
57	        static int GetDefineValue(string defineName)
58	        {
59	            string targetToken = "#define " + defineName;
60	            using var reader = new StringReader(Setup);
61	            string line;
62	            while ((line = reader.ReadLine()) != null)
63	            {
64	                line = line.Trim();
65	                if (line.StartsWith(targetToken, StringComparison.Ordinal))
66	                {
67	                    string valuePart = line.Substring(targetToken.Length).Trim();
68	                    if (int.TryParse(valuePart, out int result))
69	                        return result;
70	                }
71	            }
72	            return -1;
73	        }
74	
75	        static void SetDefineValue(string defineName, int value)
76	        {
77	            var oldValue = GetDefineValue(defineName);
78	            var defineLine = "#define " + defineName + " ";
79	            Setup = Setup.Replace(defineLine + oldValue, defineLine + value);
80	        }
81	
82	        // Injects N/SIZE from the current cube as compile-time defines (the shader arrays are sized by
83	        // them) and (re)compiles + links the existing programs so they match the cube. Called from Init
84	        // and again by CreateBuffers whenever N/SIZE change. Population / genes / generations stay as
85	        // authored in Setup.glsl.c.
86	        public static void BuildShaders()
87	        {
