89	            SetDefineValue("SIZE", TRubikCube.Size);
90	            SetDefineValue("CUBIES_COUNT", (int)Math.Pow(TRubikCube.Size, TAffine.N));
91	            TChromosome.GenesLength = GetDefineValue("GENES_COUNT");
92	            TGA<TRubikGenome>.PopulationCount = GetDefineValue("POPULATION_COUNT");
93	            TGA<TRubikGenome>.GenerationsCount = GetDefineValue("GENERATIONS_COUNT");
94	            TGA<TRubikGenome>.StallLimit = GetDefineValue("STALL_LIMIT");
95	            CompiledN = TAffine.N;
96	            CompiledSize = TRubikCube.Size;
97	
98	            CompileProgram(InitProgram, "Resources.Init.glsl.c");
99	            CompileProgram(EvaluateMicroProgram, "Resources.EvaluateMicro.glsl.c");
100	            CompileProgram(EvaluateMacroProgram, "Resources.EvaluateMacro.glsl.c");
101	            CompileProgram(SortProgram, "Resources.Sort.glsl.c");
102	            CompileProgram(SelCrossoverProgram, "Resources.SelCrossover.glsl.c");
103	        }
104	
105	        static string ReadManifestText(string dotPath)
106	        {
107	            var assembly = Assembly.GetExecutingAssembly();
108	            string rootNamespace = assembly.GetName().Name;
109	            string resourceName = $"{rootNamespace}.{dotPath}";
110	            using Stream stream = assembly.GetManifestResourceStream(resourceName);
111	            using StreamReader reader = new StreamReader(stream);
112	            return reader.ReadToEnd();
