115	        // Create a compute program and its shader and attach them (once, in Init). Sourcing, compiling
116	        // and linking happen later in BuildShaders, so an N/SIZE change just recompiles these objects.
117	        static uint CreateProgram()
118	        {
119	            var program = OpenGL.CreateProgram();
120	            var shader = OpenGL.CreateShader(OpenGL.GL_COMPUTE_SHADER);
121	            OpenGL.AttachShader(program, shader);
122	            return program;
123	        }
