125	        // (Re)source the program's single attached shader with the current Setup header, compile it and
126	        // relink. The objects already exist (created in Init); the shader handle is read back with
127	        // glGetAttachedShaders rather than cached, so the class keeps only the program handles.
128	        static void CompileProgram(uint program, string dotPath)
129	        {
130	            uint shader;
131	            int count;
132	            OpenGL.GetAttachedShaders(program, 1, &count, &shader);
133	            var code = ReadManifestText(dotPath).Replace("#include \"Setup.glsl.c\"", Setup);
134	            OpenGL.ShaderSource(shader, code);
135	            OpenGL.CompileShader(shader);
136	            int status;
137	            OpenGL.GetShaderiv(shader, OpenGL.GL_COMPILE_STATUS, &status);
138	            if (status == 0)
