159	            var active = cube.ActiveCluster.Select(c => c.StartIndex).ToArray();
160	            if (active.Length == 0) active = new int[1];
161	            // std140 array of ivec2: each element is padded to 16 bytes (vec4 alignment).
162	            var planes = new int[TAffine.Planes.Length * 4];
163	            for (int i = 0; i < TAffine.Planes.Length; i++)
164	            {
165	                planes[4 * i] = TAffine.Planes[i][0];
166	                planes[4 * i + 1] = TAffine.Planes[i][1];
167	            }
