171	            fixed (uint* p = cubies) CubiesBuffer.Update(cubies.Length * sizeof(uint), p);
172	            fixed (int* p = moves) FreeMovesBuffer.Update(moves.Length * sizeof(int), p);
173	            fixed (int* p = solved) SolvedBuffer.Update(solved.Length * sizeof(int), p);
