184	        // Runs the genetic algorithm on the GPU for the current cube (TRubikGenome.RubikCube /
185	        // TRubikGenome.FreeMoves) and returns the best specimen found.
186	        public static TRubikGenome ExecuteGA(bool isInStall)
187	        {
188	            var cube = TRubikGenome.RubikCube;
189	            var populationCount = (uint)TGA<TRubikGenome>.PopulationCount;
190	            var micro = cube.Cubies.Length <= 64;
191	            var evalProgram = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
192	
193	            // Create + upload all buffers for this run (population, packed cube, free moves, indices, planes).
194	            CreateBuffers(cube, TRubikGenome.FreeMoves);
195	            var solvedCount = (uint)cube.SolvedCubies.Count;
196	            var activeCount = (uint)cube.ActiveCluster.Count;
197	
198	            // Dispatch dims. Init/SelCrossover: 1 thread per specimen (blocks of 64).
199	            // Evaluate: micro = 1 thread/specimen; macro = 1 block (256 threads) per specimen.
200	            uint genGroups = (populationCount + 63) / 64;
201	            uint evalGroups = micro ? genGroups : populationCount;
202	
203	            int parentSlot = 0;
204	            var best = new TRubikGenome();
205	            var specimenSize = (TChromosome.GenesLength + 2) * sizeof(int);
206	            var bestBuffer = new int[specimenSize / sizeof(int)];
207	            fixed (int* bestBufPtr = bestBuffer)
208	            {
209	                // Init: fill Population[0] (binding 0) with random valid move sequences.
210	                uint timeSeed = (uint)Random.Shared.Next() | (Random.Shared.Next(2) == 0 ? 0x80000000u : 0u);
211	                OpenGL.UseProgram(InitProgram);
212	                PopulationBuffer[0].Bind();
213	                OpenGL.Uniform1ui(0, timeSeed);                 // TimeSeed
214	                OpenGL.Uniform1ui(6, NumSeeds);                 // numSeeds
215	                OpenGL.DispatchCompute(genGroups, 1, 1);
216	                OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
217	
218	                for (GenerationsCount = 0; GenerationsCount < TGA<TRubikGenome>.GenerationsCount; GenerationsCount++)
219	                {
220	                    var parent = PopulationBuffer[parentSlot];
221	                    var child = PopulationBuffer[parentSlot ^ 1];
222	
223	                    // 1. Evaluate parents (binding 0). Cluster sizes come from the host, not .length().
224	                    OpenGL.UseProgram(evalProgram);
225	                    OpenGL.Uniform1ui(4, solvedCount);
226	                    OpenGL.Uniform1ui(5, activeCount);
227	                    OpenGL.BindBufferBase(parent.Type, 0, parent.Id);
228	                    OpenGL.DispatchCompute(evalGroups, 1, 1);
229	                    OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
230	
