31	        for (uint cubieID = 0; cubieID < CUBIES_COUNT; cubieID++)
32	            local_cubies[cubieID] = TurnSingleCubie(local_cubies[cubieID], cubieID, move);
33	
34	        // 2b. SEQUENTIAL EVALUATION: the thread sums its own errors for the current step 'm'
35	        float local_fA_sum = 0.0;
36	        uint scrambled = 0u;
37	        uint local_solved_errors = 0;
38	        for (uint i = 0; i < countActive; i++) {
39	            float e = GetActiveCubieError(local_cubies[ActiveCubies[i]], maxClusterState, max_fA);
40	            local_fA_sum += e;
41	            if (e != 0.0) scrambled++;
42	        }
43	        // Endgame: once <= N active cubies remain unsolved, stop rewarding fewer of them (fewer is
44	        // not easier - a lone twisted cubie / mono-twist is very hard to escape). Amplify by
45	        // N/scrambled so the search then optimises the orientation magnitude, not the count.
46	        if (scrambled > 0u && scrambled <= uint(N))
47	            local_fA_sum *= float(N) / float(scrambled);
48	        for (uint i = 0; i < countSolved; i++)
49	            if (cubieL1(local_cubies[SolvedCubies[i]]) != 0u)
50	                local_solved_errors += 1;
51	        float current_step_fitness = float(local_solved_errors) + local_fA_sum;
52	        if (current_step_fitness < specimen_best_fitness) {
53	            specimen_best_fitness = current_step_fitness;
54	            specimen_best_moves_count = uint(m + 1);
55	        }
56	    }
