27	        // One-time GPU setup: reserve the buffers, create the program + shader objects (attached but
28	        // not yet compiled), then compile them for the current cube. Call once with a current GL context.
29	        public static void Init()
30	        {
31	            Setup = ReadManifestText("Resources.Setup.glsl.c");
