        InitProgram = CreateProgram();
        EvaluateMicroProgram = CreateProgram();
        EvaluateMacroProgram = CreateProgram();
        SortProgram = CreateProgram();
        SelCrossoverProgram = CreateProgram();

        BuildShaders();
    }

