22	// Row packing of the orientation matrix (N in range [3, 8]): bits for the column index + 1 sign bit.
23	// Equivalent to findMSB(N-1)+1, but as a compile-time constant (findMSB is not a constant expression).
24	#define BITS_FOR_COL (N <= 4 ? 2 : 3)
25	#define BITS_PER_ROW (BITS_FOR_COL + 1)
