# -*- coding: utf-8 -*-
# Shared reportlab renderer for the two Docs. System Windows fonts, subset-embedded (needed for
# Polish glyphs; the base-14 PDF fonts are Latin-1 only).
import os, re
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import (BaseDocTemplate, PageTemplate, Frame, Paragraph,
                                Preformatted, Spacer, Table, TableStyle, PageBreak, KeepTogether)
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

F = r'C:\Windows\Fonts'
def _reg(name, fn):
    p = os.path.join(F, fn)
    if os.path.exists(p):
        pdfmetrics.registerFont(TTFont(name, p)); return True
    return False
_reg('Body', 'times.ttf'); _reg('Body-B', 'timesbd.ttf'); _reg('Body-I', 'timesi.ttf'); _reg('Body-BI', 'timesbi.ttf')
pdfmetrics.registerFontFamily('Body', normal='Body', bold='Body-B', italic='Body-I', boldItalic='Body-BI')
MONO = 'Mono' if _reg('Mono', 'consola.ttf') else 'Courier'

TITLE = ParagraphStyle('title', fontName='Body-B', fontSize=17, leading=21, alignment=1, spaceAfter=6)
SUBTITLE = ParagraphStyle('subtitle', fontName='Body', fontSize=12, leading=15, alignment=1, spaceAfter=10, textColor=colors.HexColor('#333333'))
AUTH = ParagraphStyle('auth', fontName='Body', fontSize=11, leading=14, alignment=1, spaceAfter=2)
AFFIL = ParagraphStyle('affil', fontName='Body-I', fontSize=9.5, leading=12, alignment=1, spaceAfter=3, textColor=colors.HexColor('#444444'))
META = ParagraphStyle('meta', fontName='Body-I', fontSize=9.5, leading=13, alignment=1, textColor=colors.HexColor('#555555'), spaceBefore=8, spaceAfter=4)
H1 = ParagraphStyle('h1', fontName='Body-B', fontSize=12.5, leading=16, spaceBefore=11, spaceAfter=4, textColor=colors.HexColor('#14243a'))
H2 = ParagraphStyle('h2', fontName='Body-B', fontSize=10.8, leading=14, spaceBefore=6, spaceAfter=2)
BODY = ParagraphStyle('body', fontName='Body', fontSize=10, leading=13.4, alignment=4, spaceAfter=5)
BODYC = ParagraphStyle('bodyc', parent=BODY, alignment=1)
ABSTRACT = ParagraphStyle('abstract', parent=BODY, leftIndent=10, rightIndent=10, fontSize=9.6, leading=12.8, textColor=colors.HexColor('#222222'))
BULLET = ParagraphStyle('bullet', parent=BODY, leftIndent=12, spaceAfter=2)
CODE = ParagraphStyle('code', fontName=MONO, fontSize=7.6, leading=9.4, textColor=colors.HexColor('#10233a'),
                      backColor=colors.HexColor('#f3f3f6'), borderPadding=4, leftIndent=2, spaceBefore=2, spaceAfter=5)
CAP = ParagraphStyle('cap', fontName='Body-I', fontSize=8.6, leading=11, alignment=1, textColor=colors.HexColor('#555555'), spaceBefore=1, spaceAfter=6)

def esc(t): return t.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
def inl(t):
    # markup already partly escaped by caller convention: **b**, *i*, `code`, ^{sup}, _{sub}
    t = re.sub(r'\*\*(.+?)\*\*', r'<b>\1</b>', t)
    t = re.sub(r'`([^`]+)`', lambda m: '<font face="%s" size=8.6>%s</font>' % (MONO, m.group(1)), t)
    t = re.sub(r'\^\{([^}]*)\}', r'<super>\1</super>', t)
    t = re.sub(r'_\{([^}]*)\}', r'<sub>\1</sub>', t)
    t = re.sub(r'\*(?!\*)([^*]+?)\*', r'<i>\1</i>', t)
    return t

def render(blocks, out, foot):
    flow = []
    for b in blocks:
        k = b[0]
        if k == 'title': flow.append(Paragraph(esc(b[1]), TITLE))
        elif k == 'subtitle': flow.append(Paragraph(esc(b[1]), SUBTITLE))
        elif k == 'auth': flow.append(Paragraph(esc(b[1]), AUTH))
        elif k == 'affil': flow.append(Paragraph(esc(b[1]), AFFIL))
        elif k == 'meta': flow.append(Paragraph(inl(esc(b[1])), META))
        elif k == 'h1': flow.append(Paragraph(inl(esc(b[1])), H1))
        elif k == 'h2': flow.append(Paragraph(inl(esc(b[1])), H2))
        elif k == 'body': flow.append(Paragraph(inl(esc(b[1])), BODY))
        elif k == 'bodyc': flow.append(Paragraph(inl(esc(b[1])), BODYC))
        elif k == 'abstract': flow.append(Paragraph(inl(esc(b[1])), ABSTRACT))
        elif k == 'bullet': flow.append(Paragraph('&bull;&nbsp;' + inl(esc(b[1])), BULLET))
        elif k == 'code': flow.append(Preformatted(b[1], CODE))
        elif k == 'cap': flow.append(Paragraph(inl(esc(b[1])), CAP))
        elif k == 'space': flow.append(Spacer(1, b[1]))
        elif k == 'pagebreak': flow.append(PageBreak())
        elif k == 'table':
            rows = b[1]
            data = [[Paragraph(inl(esc(c)), ParagraphStyle('tc', fontName='Body', fontSize=8.6, leading=11)) for c in r] for r in rows]
            data[0] = [Paragraph('<b>%s</b>' % inl(esc(c)), ParagraphStyle('th', fontName='Body-B', fontSize=8.8, leading=11, textColor=colors.white)) for c in rows[0]]
            t = Table(data, colWidths=b[2] if len(b) > 2 else None, repeatRows=1)
            t.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#14243a')),
                ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#f2f4f7')]),
                ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#cccccc')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 4), ('RIGHTPADDING', (0, 0), (-1, -1), 4),
                ('TOPPADDING', (0, 0), (-1, -1), 2.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 2.5),
            ]))
            flow.append(t); flow.append(Spacer(1, 4))

    def _foot(canvas, doc):
        canvas.saveState(); canvas.setFont('Body', 8); canvas.setFillColor(colors.HexColor('#888888'))
        canvas.drawCentredString(A4[0] / 2, 10 * mm, "%s — str. %d" % (foot, doc.page))
        canvas.restoreState()
    doc = BaseDocTemplate(out, pagesize=A4, leftMargin=20 * mm, rightMargin=20 * mm, topMargin=17 * mm, bottomMargin=16 * mm)
    fr = Frame(doc.leftMargin, doc.bottomMargin, doc.width, doc.height, id='n')
    doc.addPageTemplates([PageTemplate(id='m', frames=[fr], onPage=_foot)])
    doc.build(flow)
    print("wrote", out, os.path.getsize(out), "bytes")

