        public static TMove Decode(int code)
        {
            var move = new TMove();
            move.Angle = code & 3;
            move.Plane = (code >> 2) & 31;
            move.Axis = (code >> 7) & 7;
            move.Slice = code >> 10;
            return move;
        }

        public int Encode()
        {
            int code = 0;
            code |= Angle & 3;
            code |= (Plane & 31) << 2;
            code |= (Axis & 7) << 7;
            code |= Slice << 10;
            return code;
        }


        //public static int GetRevCode(int code) { return code + 2 * (1 - code % 3); }
        public static int GetRevCode(int code)
        {
            int oldAngle = code & 3;
            int newAngle = 2 - oldAngle;
            return (code & ~3) | newAngle;
        }

