146	        // ids/bindings and resizes the store as needed, so there is no buffer churn between GA runs.
147	        public static void CreateBuffers(TRubikCube cube)
148	        {
149	            // Keep the shader in sync with the cube: N/SIZE are compile-time defines, so recompile
150	            // when the dimension or size changed, otherwise the shader reads Cubies out of bounds.
151	            if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
152	                BuildShaders();         
153	            var populationSize = TGA<TRubikGenome>.PopulationCount * (TChromosome.GenesLength + 2) * sizeof(int);
154	            var cubies = cube.PackCubies();
155	            var moves = TRubikGenome.FreeMoves.ToArray();
156	            // Pad empty index arrays to one element so we never make a zero-size SSBO (unreliable
157	            // .length() / binding). The countSolved / countActive uniforms gate the loops.
158	            var solved = cube.SolvedCubies.Select(c => c.StartIndex).ToArray();
