186	        }
187	
188	        // Scores the current cube on the GPU with the SAME evaluator the GA uses: a zero specimen (all
189	        // genes 0 = 0-degree identity moves after the quarter-turn encoding) leaves the cube unchanged,
190	        // so the evaluator returns baseline + no-op penalty. We subtract the penalty - MEASURED, not
191	        // hardcoded, as the same zero specimen's fitness on a SOLVED cube (baseline == 0, so the fitness
192	        // is exactly the penalty). One scorer (the evaluator), no separate kernel, no magic constant,
193	        // and the baseline tracks any future change to the no-op penalty automatically.
194	        static float noOpPenalty;   // reset to NaN in BuildShaders (Init + on N/SIZE change) -> measured on first ScoreCube
