203	        // Evaluates ONE all-zero specimen (identity
204	        // moves) and returns its fitness = the cube's raw score PLUS the no-op penalty (a zero specimen
205	        // never changes the active cluster, so the penalty always fires).
206	        static float EvalZeroSpecimen(TRubikCube cube)
207	        {
208	            CreateBuffers(cube);
209	            var micro = cube.Cubies.Length <= 64;
210	            var eval = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
211	            var spec = new int[TChromosome.GenesLength + 2];   // all zero = identity moves
212	            fixed (int* p = spec) Population.Update(spec.Length * sizeof(int), p);
213	            OpenGL.UseProgram(eval);
214	            OpenGL.Uniform1ui(4, (uint)cube.SolvedCubies.Count);
215	            OpenGL.Uniform1ui(5, (uint)cube.ActiveCluster.Count);
216	            OpenGL.BindBufferBase(Population.Type, 0, Population.Id);
217	            OpenGL.DispatchCompute(1, 1, 1);                        // one specimen: 1 thread (micro) / 1 block (macro)
218	            OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
219	            var result = new int[1];
220	            OpenGL.BindBuffer(Population.Type, Population.Id);
221	            fixed (int* rp = result)
222	                OpenGL.GetBufferSubData(Population.Type, 0, sizeof(float), rp);
223	            return BitConverter.Int32BitsToSingle(result[0]);
224	        }
225	
226	        // Runs the genetic algorithm on the GPU for the current cube (TRubikGenome.RubikCube /
227	        // TRubikGenome.FreeMoves) and returns the best specimen found.
228	        public static TRubikGenome ExecuteGA()
229	        {
230	            var cube = TRubikGenome.RubikCube;
231	            var populationCount = (uint)TGA<TRubikGenome>.PopulationCount;
232	            var micro = cube.Cubies.Length <= 64;
233	            var evalProgram = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
234	
235	            // Create + upload all buffers for this run (population, packed cube, free moves, indices, planes).
236	            CreateBuffers(cube);
237	            var solvedCount = (uint)cube.SolvedCubies.Count;
238	            var activeCount = (uint)cube.ActiveCluster.Count;
239	
240	            // Dispatch dims. Init/SelCrossover: 1 thread per specimen (blocks of 64).
241	            // Evaluate: micro = 1 thread/specimen; macro = 1 block (256 threads) per specimen.
242	            uint genGroups = (populationCount + 63) / 64;
243	            uint evalGroups = micro ? genGroups : populationCount;
244	
245	            int parentSlot = 0;
246	            var best = new TRubikGenome();
247	            var specimenSize = (TChromosome.GenesLength + 2) * sizeof(int);
248	            var bestBuffer = new int[specimenSize / sizeof(int)];
249	            fixed (int* bestBufPtr = bestBuffer)
250	            {
251	                // Init: fill the population (binding 0) with random valid move sequences.
252	                uint timeSeed = (uint)Random.Shared.Next() | (Random.Shared.Next(2) == 0 ? 0x80000000u : 0u);
253	                OpenGL.UseProgram(InitProgram);
254	                Population.Bind();
255	                OpenGL.Uniform1ui(0, timeSeed);                 // TimeSeed
256	                OpenGL.Uniform1ui(6, NumSeeds);                 // numSeeds
257	                OpenGL.DispatchCompute(genGroups, 1, 1);
258	                OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
259	
260	                var pop = new[] { Population, Children };   // local ping-pong pair (binding 0/1 swap each gen)
261	                for (GenerationsCount = 0; GenerationsCount < TGA<TRubikGenome>.GenerationsCount; GenerationsCount++)
262	                {
263	                    var parent = pop[parentSlot];
264	                    var child = pop[parentSlot ^ 1];
265	
266	                    // 1. Evaluate parents (binding 0). Cluster sizes come from the host, not .length().
267	                    OpenGL.UseProgram(evalProgram);
268	                    OpenGL.Uniform1ui(4, solvedCount);
269	                    OpenGL.Uniform1ui(5, activeCount);
270	                    OpenGL.BindBufferBase(parent.Type, 0, parent.Id);
271	                    OpenGL.DispatchCompute(evalGroups, 1, 1);
272	                    OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
273	
274	                    // 2. Bitonic sort: smallest fitness ends up at index 0. u_Stage=2, u_PassModStage=3.
275	                    OpenGL.UseProgram(SortProgram);
276	                    for (uint stage = 2; stage <= populationCount; stage <<= 1)
277	                    {
278	                        OpenGL.Uniform1ui(2, stage);
279	                        for (uint passModStage = stage >> 1; passModStage > 0; passModStage >>= 1)
280	                        {
281	                            OpenGL.Uniform1ui(3, passModStage);
282	                            OpenGL.DispatchCompute(populationCount / 256, 1, 1);
283	                            OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
284	                        }
285	                    }
286	
287	                    // 3. Read the best specimen (Population[parentSlot][0] after the sort).
288	                    OpenGL.BindBuffer(parent.Type, parent.Id);
289	                    OpenGL.GetBufferSubData(parent.Type, 0, specimenSize, bestBufPtr);
290	                    var fitness = BitConverter.UInt32BitsToSingle((uint)bestBuffer[0]);
291	                    if (fitness < best.Fitness)
292	                    {
293	                        best.ReadBuffer(bestBuffer);
294	                        if (best.Fitness < cube.Score)
295	                            return best;
296	                    }
297	
298	                    // 4. Selection + crossover: parents at binding 0, children written to binding 1.
299	                    OpenGL.UseProgram(SelCrossoverProgram);
300	                    OpenGL.BindBufferBase(parent.Type, 0, parent.Id);
301	                    OpenGL.BindBufferBase(child.Type, 1, child.Id);
302	                    OpenGL.Uniform1ui(0, timeSeed++);           // TimeSeed
303	                    OpenGL.Uniform1ui(6, NumSeeds);             // numSeeds
304	                    OpenGL.DispatchCompute(genGroups, 1, 1);
305	                    OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
306	
307	                    // 5. Ping-pong: this generation's children are next generation's parents.
308	                    parentSlot ^= 1;
309	                }
310	            }
311	            return best;
312	        }
313	    }
314	}
315	#endif
