#version 430
// Instanced hypercube render. N is injected at compile time (like the GA shaders).
// Base positions are ND (may exceed a vec4), so they are vertex-pulled from an SSBO by
// gl_VertexID; the per-instance ND world transform (M column-major + Origin) is pulled
// from another SSBO by gl_InstanceID. Projection = orthographic (drop coords >= 3).
#define N 1
layout(std430, binding = 0) buffer Pos    { float basePos[]; };   // N floats per base vertex
layout(std430, binding = 1) buffer Xforms { float world[];   };   // (N*N + N) floats per instance

layout(location = 0) in vec2 uv;
layout(location = 1) in vec4 color;

out vec2 fUv;
out vec4 fCol;
out vec3 fPos;

void main()
{
    int vb = gl_VertexID * N;
    int mb = gl_InstanceID * (N * N + N);
    float o[N];
    for (int r = 0; r < N; r++)
    {
        float s = world[mb + N * N + r];                    // Origin[r]
        for (int c = 0; c < N; c++)
            s += world[mb + c * N + r] * basePos[vb + c];   // M[r,c] * p[c]   (M is column-major)
        o[r] = s;
    }
    vec3 p3 = vec3(0.0);                                     // ortho ND->3D: keep first up-to-3 coords
    for (int i = 0; i < min(N, 3); i++) p3[i] = o[i];
    gl_Position = vec4(p3, 1.0);
    fPos = p3;
    fUv = uv;
    fCol = color;
}

