186	        // Scores the current cube on the GPU with the SAME evaluator the GA uses: a zero specimen (all
187	        // genes 0 = 0-degree identity moves after the quarter-turn encoding) leaves the cube unchanged,
188	        // so the evaluator returns baseline + no-op penalty. We subtract the penalty - MEASURED, not
189	        // hardcoded, as the same zero specimen's fitness on a SOLVED cube (baseline == 0, so the fitness
190	        // is exactly the penalty). One scorer (the evaluator), no separate kernel, no magic constant,
191	        // and the baseline tracks any future change to the no-op penalty automatically.
192	        static float noOpPenalty;   // reset to NaN in BuildShaders (Init + on N/SIZE change) -> measured on first ScoreCube
193	        public static float ScoreCube(TRubikCube cube)
194	        {
195	            var score = EvalZeroSpecimen(cube);
196	            if (float.IsNaN(noOpPenalty))
197	                noOpPenalty = EvalZeroSpecimen(new TRubikCube());
198	            return score - noOpPenalty;
199	        }
200	
201	        // Evaluates ONE all-zero specimen (identity
202	        // moves) and returns its fitness = the cube's raw score PLUS the no-op penalty (a zero specimen
203	        // never changes the active cluster, so the penalty always fires).
204	        static float EvalZeroSpecimen(TRubikCube cube)
205	        {
206	            CreateBuffers(cube);
207	            var micro = cube.Cubies.Length <= 64;
208	            var eval = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
209	            var spec = new int[TChromosome.GenesLength + 2];   // all zero = identity moves
210	            fixed (int* p = spec) Population.Update(spec.Length * sizeof(int), p);
211	            OpenGL.UseProgram(eval);
212	            OpenGL.Uniform1ui(4, (uint)cube.SolvedCubies.Count);
213	            OpenGL.Uniform1ui(5, (uint)cube.ActiveCluster.Count);
214	            OpenGL.BindBufferBase(Population.Type, 0, Population.Id);
215	            OpenGL.DispatchCompute(1, 1, 1);                        // one specimen: 1 thread (micro) / 1 block (macro)
216	            OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
217	            var result = new int[1];
218	            OpenGL.BindBuffer(Population.Type, Population.Id);
219	            fixed (int* rp = result)
220	                OpenGL.GetBufferSubData(Population.Type, 0, sizeof(float), rp);
221	            return BitConverter.Int32BitsToSingle(result[0]);
222	        }
223	
224	        // Runs the genetic algorithm on the GPU for the current cube (TRubikGenome.RubikCube /
225	        // TRubikGenome.FreeMoves) and returns the best specimen found.
226	        public static TRubikGenome ExecuteGA()
227	        {
228	            var cube = TRubikGenome.RubikCube;
229	            var populationCount = (uint)TGA<TRubikGenome>.PopulationCount;
230	            var micro = cube.Cubies.Length <= 64;
231	            var evalProgram = micro ? EvaluateMicroProgram : EvaluateMacroProgram;
232	
233	            // Create + upload all buffers for this run (population, packed cube, free moves, indices, planes).
234	            CreateBuffers(cube);
235	            var solvedCount = (uint)cube.SolvedCubies.Count;
236	            var activeCount = (uint)cube.ActiveCluster.Count;
237	
238	            // Dispatch dims. Init/SelCrossover: 1 thread per specimen (blocks of 64).
239	            // Evaluate: micro = 1 thread/specimen; macro = 1 block (256 threads) per specimen.
240	            uint genGroups = (populationCount + 63) / 64;
241	            uint evalGroups = micro ? genGroups : populationCount;
242	
243	            int parentSlot = 0;
244	            var best = new TRubikGenome();
245	            var specimenSize = (TChromosome.GenesLength + 2) * sizeof(int);
246	            var bestBuffer = new int[specimenSize / sizeof(int)];
247	            fixed (int* bestBufPtr = bestBuffer)
248	            {
249	                // Init: fill the population (binding 0) with random valid move sequences.
250	                uint timeSeed = (uint)Random.Shared.Next() | (Random.Shared.Next(2) == 0 ? 0x80000000u : 0u);
251	                OpenGL.UseProgram(InitProgram);
252	                Population.Bind();
253	                OpenGL.Uniform1ui(0, timeSeed);                 // TimeSeed
254	                OpenGL.Uniform1ui(6, NumSeeds);                 // numSeeds
255	                OpenGL.DispatchCompute(genGroups, 1, 1);
256	                OpenGL.MemoryBarrier(OpenGL.MemoryBarrierFlags.ShaderStorage);
257	
258	                var pop = new[] { Population, Children };   // local ping-pong pair (binding 0/1 swap each gen)
259	                for (GenerationsCount = 0; GenerationsCount < TGA<TRubikGenome>.GenerationsCount; GenerationsCount++)
260	                {
261	                    var parent = pop[parentSlot];
262	                    var child = pop[parentSlot ^ 1];
263	
264	                    // 1. Evaluate parents (binding 0). Cluster sizes come from the host, not .length().
265	                    OpenGL.UseProgram(evalProgram);
266	                    OpenGL.Uniform1ui(4, solvedCount);
267	                    OpenGL.Uniform1ui(5, activeCount);
