        // Compiles one render shader (VS/FS) with N injected into its own #define (not the Setup header).
        static void CompileRenderShader(uint shader, string dotPath)
        {
            var src = ReadManifestText(dotPath).Replace("#define N 1", "#define N " + TAffine.N);
            OpenGL.ShaderSource(shader, src);
            OpenGL.CompileShader(shader);
            int status;
            OpenGL.GetShaderiv(shader, OpenGL.GL_COMPILE_STATUS, &status);
            if (status == 0)
                throw new Exception(OpenGL.GetShaderInfoLog(shader));
        }

        // (Re)builds the shared base hypercube mesh into the render buffers from TCubie.Cube: base ND
        // positions -> PosBuffer (vertex-pulled), interleaved uv+color -> VAO, triangulated quads -> EBO.
        static void BuildCubeMesh()
        {
            var mesh = TCubie.Cube;
            int n = TAffine.N;
            int faceCount = mesh.Colors.Count;      // one color per quad face
            int vertCount = 4 * faceCount;          // quads expanded per-face (uv/color differ per face)
            cubeIndexCount = 6 * faceCount;         // two triangles per quad

            var pos = new float[n * vertCount];
            var attr = new byte[12 * vertCount];    // interleaved: uv (2 float) + color (4 byte)
            var idx = new uint[cubeIndexCount];
            var quadUv = new float[] { 0, 0, 1, 0, 1, 1, 0, 1 };
            fixed (byte* pa = attr)
            {
                for (int f = 0; f < faceCount; f++)
                {
                    var col = mesh.Colors[f];
                    for (int k = 0; k < 4; k++)
                    {
                        int v = 4 * f + k;
                        var corner = mesh.Vertices[mesh.Faces[4 * f + k]];
                        for (int d = 0; d < n; d++)
                            pos[n * v + d] = corner.Data[d];
                        float* fu = (float*)(pa + 12 * v);
                        fu[0] = quadUv[2 * k];
                        fu[1] = quadUv[2 * k + 1];
                        byte* bc = pa + 12 * v + 8;
                        bc[0] = col.R; bc[1] = col.G; bc[2] = col.B; bc[3] = 255;
                    }
                    int b = 4 * f, o = 6 * f;
                    idx[o] = (uint)b; idx[o + 1] = (uint)(b + 1); idx[o + 2] = (uint)(b + 2);
                    idx[o + 3] = (uint)b; idx[o + 4] = (uint)(b + 2); idx[o + 5] = (uint)(b + 3);
                }
            }

            OpenGL.BindVertexArray(cubeVao);
            OpenGL.BindBuffer(OpenGL.GL_ARRAY_BUFFER, attrBuf);
            fixed (byte* pa = attr)
                OpenGL.BufferData(OpenGL.GL_ARRAY_BUFFER, attr.Length, pa, OpenGL.GL_STATIC_DRAW);
            OpenGL.VertexAttribPointer(0, 2, OpenGL.GL_FLOAT, (byte)0, 12, (void*)0);           // uv
            OpenGL.EnableVertexAttribArray(0);
            OpenGL.VertexAttribPointer(1, 4, OpenGL.GL_UNSIGNED_BYTE, (byte)1, 12, (void*)8);   // color (normalized)
            OpenGL.EnableVertexAttribArray(1);
            OpenGL.BindBuffer(OpenGL.GL_ELEMENT_ARRAY_BUFFER, idxBuf);
            fixed (uint* pi = idx)
                OpenGL.BufferData(OpenGL.GL_ELEMENT_ARRAY_BUFFER, idx.Length * sizeof(uint), pi, OpenGL.GL_STATIC_DRAW);
            OpenGL.BindVertexArray(0);

            fixed (float* pp = pos) PosBuffer.Update(pos.Length * sizeof(float), pp);
        }

        // Draws every cubie as an instance of the shared base mesh. TGLContext gathers the accumulated ND
        // world transforms (Root * ... * cubie) and passes them; we pack M (column-major) + Origin per
        // instance into XformBuffer and issue one instanced draw. Rebuilds programs+mesh on N/SIZE change.
        public static void DrawCube(List<TAffine> instances)
        {
            if (CompiledN != TAffine.N || CompiledSize != TRubikCube.Size)
                BuildShaders();

            int n = TAffine.N, inst = instances.Count, stride = n * n + n;
            if (xformScratch == null || xformScratch.Length < stride * inst)
                xformScratch = new float[stride * inst];
            for (int i = 0; i < inst; i++)
            {
                Array.Copy(instances[i].M.Data, 0, xformScratch, i * stride, n * n);           // M (column-major)
                Array.Copy(instances[i].Origin.Data, 0, xformScratch, i * stride + n * n, n);   // Origin
            }
            fixed (float* p = xformScratch) XformBuffer.Update(stride * inst * sizeof(float), p);

            OpenGL.UseProgram(RenderProgram);
            PosBuffer.Bind();       // binding 8
            XformBuffer.Bind();     // binding 9
            OpenGL.BindVertexArray(cubeVao);
            OpenGL.DrawElementsInstanced(OpenGL.GL_TRIANGLES, cubeIndexCount, OpenGL.GL_UNSIGNED_INT, (void*)0, inst);
            OpenGL.BindVertexArray(0);
        }
    }
}

