void BuildCube()
{
    var mesh = TCubie.Cube;
    int n = TAffine.N;
    int faceCount = mesh.Colors.Count;      // one color per quad face
    int vertCount = 4 * faceCount;          // quads expanded per-face (uv/color differ per face)
    cubeIndexCount = 6 * faceCount;         // two triangles per quad

    var pos = new float[n * vertCount];     // base ND positions, vertex-pulled by gl_VertexID
    var attr = new byte[12 * vertCount];    // interleaved: uv (2 float) + color (4 byte)
    var idx = new uint[cubeIndexCount];
    var quadUv = new float[] { 0, 0, 1, 0, 1, 1, 0, 1 };
    fixed (byte* pa = attr)
    {
        for (int f = 0; f < faceCount; f++)
        {
            var col = mesh.Colors[f];
            for (int k = 0; k < 4; k++)
            {
                int v = 4 * f + k;
                var corner = mesh.Vertices[mesh.Faces[4 * f + k]];
                for (int d = 0; d < n; d++)
                    pos[n * v + d] = corner.Data[d];
                float* fu = (float*)(pa + 12 * v);
                fu[0] = quadUv[2 * k];
                fu[1] = quadUv[2 * k + 1];
                byte* bc = pa + 12 * v + 8;
                bc[0] = col.R; bc[1] = col.G; bc[2] = col.B; bc[3] = 255;
            }
            int b = 4 * f, o = 6 * f;
            idx[o] = (uint)b; idx[o + 1] = (uint)(b + 1); idx[o + 2] = (uint)(b + 2);
            idx[o + 3] = (uint)b; idx[o + 4] = (uint)(b + 2); idx[o + 5] = (uint)(b + 3);
        }
    }

    if (cubeVao == 0)
    {
        uint id;
        OpenGL.GenVertexArrays(1, &id); cubeVao = id;
        OpenGL.GenBuffers(1, &id); posBuf = id;
        OpenGL.GenBuffers(1, &id); attrBuf = id;
        OpenGL.GenBuffers(1, &id); idxBuf = id;
        OpenGL.GenBuffers(1, &id); xformBuf = id;
    }

    OpenGL.BindVertexArray(cubeVao);
    OpenGL.BindBuffer(OpenGL.GL_ARRAY_BUFFER, attrBuf);
    fixed (byte* pa = attr)
        OpenGL.BufferData(OpenGL.GL_ARRAY_BUFFER, attr.Length, pa, OpenGL.GL_STATIC_DRAW);
    OpenGL.VertexAttribPointer(0, 2, OpenGL.GL_FLOAT, (byte)0, 12, (void*)0);           // uv
    OpenGL.EnableVertexAttribArray(0);
    OpenGL.VertexAttribPointer(1, 4, OpenGL.GL_UNSIGNED_BYTE, (byte)1, 12, (void*)8);   // color (normalized)
    OpenGL.EnableVertexAttribArray(1);
    OpenGL.BindBuffer(OpenGL.GL_ELEMENT_ARRAY_BUFFER, idxBuf);
    fixed (uint* pi = idx)
        OpenGL.BufferData(OpenGL.GL_ELEMENT_ARRAY_BUFFER, idx.Length * sizeof(uint), pi, OpenGL.GL_STATIC_DRAW);
    OpenGL.BindVertexArray(0);

    OpenGL.BindBuffer(OpenGL.GL_SHADER_STORAGE_BUFFER, posBuf);
    fixed (float* pp = pos)
        OpenGL.BufferData(OpenGL.GL_SHADER_STORAGE_BUFFER, pos.Length * sizeof(float), pp, OpenGL.GL_STATIC_DRAW);

    BuildCubeProgram(n);
    cubeCompiledN = n;
    cubeCompiledSize = TRubikCube.Size;
}

void BuildCubeProgram(int n)
{
    if (cubeProgram == 0)
    {
        cubeProgram = OpenGL.CreateProgram();
        cubeVs = OpenGL.CreateShader(OpenGL.GL_VERTEX_SHADER);
        cubeFs = OpenGL.CreateShader(OpenGL.GL_FRAGMENT_SHADER);
        OpenGL.AttachShader(cubeProgram, cubeVs);
        OpenGL.AttachShader(cubeProgram, cubeFs);
    }
    CompileCubeShader(cubeVs, "Resources.CubeVertex.glsl.c", n);
    CompileCubeShader(cubeFs, "Resources.CubeFragment.glsl.c", n);
    OpenGL.LinkProgram(cubeProgram);
}

void CompileCubeShader(uint shader, string dotPath, int n)
{
    var src = ReadManifestText(dotPath).Replace("#define N 1", "#define N " + n);
    OpenGL.ShaderSource(shader, src);
    OpenGL.CompileShader(shader);
    int status;
    OpenGL.GetShaderiv(shader, OpenGL.GL_COMPILE_STATUS, &status);
    if (status == 0)
        throw new Exception(OpenGL.GetShaderInfoLog(shader));
}

static string ReadManifestText(string dotPath)
{
    var asm = Assembly.GetExecutingAssembly();
    using var s = asm.GetManifestResourceStream(asm.GetName().Name + "." + dotPath);
    using var r = new StreamReader(s);
    return r.ReadToEnd();
}

